			// (its pgid equals its pid). Required for SIGSTOP / SIGKILL
			// to affect the bash subprocesses it spawns — without it,
			// `process.kill(-pid, ...)` would target *our* process group
			// and freeze/kill the whole parent.
			const proc = spawn(invocation.command, invocation.args, {
				cwd: effectiveCwd,
				shell: false,
				stdio: ["ignore", "pipe", "pipe"],
				detached: true,
			});
