				if (idleTimer) clearTimeout(idleTimer);
				idleTimer = setTimeout(() => {
					// Watchdog fired. Freeze the process group and resolve
					// with a suspension id, OR (on win32) immediately
					// SIGKILL the group and resolve as a failed exit.
					idleTimer = null;
					const frozen = freezeProcessGroup(proc);
					if (!frozen) {
