			});

			proc.stderr.on("data", (data) => {
				lastEventAtMs = Date.now();
				armWatchdog();
				currentResult.stderr += data.toString();
			});

			proc.on("close", (code) => {
				disarmWatchdog();
				if (buffer.trim()) processLine(buffer);
				currentResult.exitCode = code ?? 0;
				resolve({ kind: "exit", result: { ...currentResult } });
			});

			proc.on("error", () => {
				disarmWatchdog();
				currentResult.exitCode = 1;
				resolve({ kind: "exit", result: { ...currentResult } });
			});

			// Abort handling. The handler is detached on suspend and
			// re-attached on resume, so the registry (not a closure)
			// decides whether a given Ctrl+C should reach the process.
			const abortHandler = (() => {
				const h = () => {
					// Defensive: if we already suspended or the proc
					// died, do nothing. SIGTERM'ing a stopped process
					// is a no-op until SIGCONT, and SIGTERM'ing a dead
					// process throws ESRCH.
					if (proc.exitCode !== null) return;
					wasAborted = true;
					try {
						if (proc.pid) process.kill(-proc.pid, "SIGTERM");
