				if (r0) {
					allResults[index] = r0;
					emitParallelUpdate();
				}
			},
			makeDetails("parallel"),
			allToolNames,
			t.model ?? modelOverride,
			{
				kind: "parallel",
				index,
				taskSpec: t,
