/**
 * `inspect` — return more tail lines for a frozen process.
 *
 * Pure read; we do not touch the process. If the suspension is gone
 * (already resumed / killed / never existed), we return an error text
 * so the LLM can adjust.
 */
function handleInspect(
	inspectParams: { id: string; lines?: number },
	ctx: { cwd: string },
	makeDetails: (mode: "single" | "parallel" | "chain", suspensions?: SuspendedSnapshot["suspensions"]) => (results: SingleResult[]) => SubagentDetails | SuspendedSnapshot,
): AgentToolResult<SubagentDetails | SuspendedSnapshot> {
	const lines = inspectParams.lines ?? DEFAULT_INSPECT_LINES;
	const susp = getSuspension(inspectParams.id);
	if (!susp) {
		return {
			content: [
				{
					type: "text",
					text: `No active suspension with id "${inspectParams.id}". It may have been resumed, killed, or never existed.`,
				},
			],
			details: makeDetails("single")([]),
		};
	}
	const tail = summarizeTail(susp.messages, susp.stderr, lines);
	// Compute `inFlight` LIVE rather than trusting the frozen
	// snapshot. While suspended the recorded `susp.inFlight` could
	// be stale if a second freeze ever lands (e.g. resume → freeze
	// → user calls `inspect` instead of resume/kill); re-walking
	// `susp.messages` for an unmatched `toolCall` always gives the
	// currently-pending call. (Also defensively correct on the
	// first freeze.)
	const inFlightLive = extractInFlight(susp.messages);
	const idleMs = Date.now() - susp.lastEventAtMs;
	const text = JSON.stringify(
		{
			status: "idle_inspect",
			suspensionId: susp.id,
			idleMs,
			runningCommand: inFlightLive?.command ?? null,
			requestedTimeout: inFlightLive?.timeout ?? null,
			tail,
		},
		null,
		2,
	);
	return {
		content: [{ type: "text", text }],
		details: makeDetails("single")([liteToSingle(susp.partialResult)]),
	};
}

/**
 * `kill` — thaw then SIGKILL the process group, finalize the
 * suspension, return the partial transcript.
 *
 * Symmetric to handleResume. After kill we never re-attach the abort
 * handler (the process is dead), and the suspension is unregistered
 * synchronously.
 */
function handleKill(
	id: string,
	ctx: { cwd: string },
	makeDetails: (mode: "single" | "parallel" | "chain", suspensions?: SuspendedSnapshot["suspensions"]) => (results: SingleResult[]) => SubagentDetails | SuspendedSnapshot,
): AgentToolResult<SubagentDetails | SuspendedSnapshot> {
	const susp = getSuspension(id);
	if (!susp) {
		return {
			content: [
				{
					type: "text",
					text: `No active suspension with id "${id}". It may have been resumed, killed, or never existed.`,
				},
			],
			details: makeDetails("single")([]),
		};
	}

	// Thaw before kill. SIGKILL to a stopped process works at the
	// kernel level, but thawing first lets any pending cleanup (file
	// handles, child waits) unwind. We add a small delay to give the
	// OS a chance to deliver queued signals.
	thawProcessGroup(susp.proc);

	// Deliberately do NOT re-attach the user's AbortSignal: the
	// process is about to die and a late-arriving Ctrl+C after the
	// kill returns would only confuse the LLM with a second error.

	setTimeout(() => killProcessGroup(susp.proc), 100);

	// Mark the partial result as aborted so isFailedResult returns true
	// and the LLM sees it as a hard failure.
	const partial: SingleResult = {
		...susp.partialResult,
		exitCode: -1,
		stopReason: "aborted",
	};

	// Unregister immediately so subsequent resume / inspect on this id
	// correctly errors out.
	unregisterSuspension(susp.id);
	return {
		content: [
			{
				type: "text",
				text: `Killed suspended sub-agent ${susp.partialResult.agent}. Partial transcript follows:\n\n${getFinalOutput(partial.messages) || "(no output)"}`,
			},
		],
		details: makeDetails("single")([partial]),
	};
}

