		// Wire stdout/stderr again. They were already wired before the
		// freeze, but Node event listeners are kept across SIGSTOP, so
		// the listeners are intact. We just need to re-arm the
		// watchdog timer.
		const onStdoutData = (data: Buffer) => {
			lastEventAtMs = Date.now();
			armWatchdog();
			buffer += data.toString();
			const lines = buffer.split("\n");
			buffer = lines.pop() || "";
			for (const line of lines) processLine(line);
		};
		const onStderrData = (data: Buffer) => {
			lastEventAtMs = Date.now();
			armWatchdog();
			partial.stderr += data.toString();
		};

		proc.stdout?.on("data", onStdoutData);
		proc.stderr?.on("data", onStderrData);

		const finalizeAndContinue = (result: SingleResult, job: Job) => {
			disarmWatchdog();
			unregisterSuspension(susp.id);

			if (job.kind === "single") {
				const isError = isFailedResult(result);
				const out = getFinalOutput(result.messages) || "(no output)";
				resolve({
					content: isError
						? [{ type: "text", text: `Agent ${result.stopReason || "failed"}: ${out}` }]
						: [{ type: "text", text: out }],
					details: makeDetails("single")([result]),
					isError,
				});
				return;
			}
			if (job.kind === "chain") {
				// Continue the chain from `job.index` using the partial
				// result we just resumed as step `job.index`.
				const allResults: SingleResult[] = [...job.results.map(liteToSingle), result];
				const previousOutput = getFinalOutput(result.messages);
				resolve(
					runChainRemaining(
						job.steps.slice(job.index + 1),
						job.index + 1,
						previousOutput,
						allResults,
						job.steps,
						ctx,
						signal,
						onUpdate,
						agents,
						allToolNames,
						agentScope,
						discovery,
						makeDetails,
						modelOverride,
					),
				);
				return;
			}
			if (job.kind === "parallel") {
				// Rebuild a fully-ordered result array of length
				// `tasks.length` from the original task spec — NOT
				// from `completedResults` (which excludes the
				// suspended index and so is one slot short). For
				// every completed sibling we lift the lite back to
				// a `SingleResult`; the resumed `result` is dropped
				// into its original index verbatim.
				const merged: SingleResult[] = new Array(job.tasks.length);
				let sibCursor = 0;
				for (let i = 0; i < job.tasks.length; i++) {
					if (i === job.index) {
						merged[i] = result;
					} else {
						merged[i] = liteToSingle(job.completedResults[sibCursor]!);
						sibCursor++;
					}
				}
				const successCount = merged.filter((r) => !isFailedResult(r)).length;
				const summaries = merged.map((r) => {
					const output = truncateParallelOutput(getResultOutput(r));
					const status = isFailedResult(r)
						? `failed${r.stopReason && r.stopReason !== "end" ? ` (${r.stopReason})` : ""}`
						: "completed";
					return `### [${r.agent}] ${status}\n\n${output}`;
				});
				resolve({
					content: [
						{
							type: "text",
							text: `Parallel: ${successCount}/${merged.length} succeeded\n\n${summaries.join("\n\n---\n\n")}`,
						},
					],
					details: makeDetails("parallel")(merged),
				});
				return;
			}
		};

		proc.once("close", (code) => {
			if (buffer.trim()) processLine(buffer);
			const result: SingleResult = { ...partial, exitCode: code ?? 0 };
			finalizeAndContinue(result, susp.job);
		});

		proc.once("error", () => {
			const result: SingleResult = { ...partial, exitCode: 1 };
			finalizeAndContinue(result, susp.job);
		});

		// Re-attach the user's AbortSignal so Ctrl+C works on the
		// resumed leg. The helper returns the same function reference
		// we need to detach on a subsequent freeze, so we MUST keep
		// it in `activeAbortHandler` rather than discard it (the
		// previous code did, which leaked the listener into the
		// user's signal for the rest of the lifetime and meant a
		// SIGTERM on the second-leg Ctrl+C ended up racing the
		// next resume's kill decision).
		activeAbortHandler = reAttachAbortListener(signal, proc, {
			isSuspended: () => resumedSuspended,
		});

		// Arm the watchdog immediately.
		armWatchdog();
	});
}

