// `finalized` flips to true the moment we resolve the
// outer promise. After that the close / error handlers
// are inert — even if the proc fires a final `close`
// (e.g. because handleKill just SIGKILL'd it after we
// resolved from a re-freeze), we MUST NOT spawn a second
// set of chain / parallel remaining steps. That was the
// R1 hang: the close handler would call `resolve(...)`
// again (no-op for the promise itself) but the ARGUMENT
// to resolve is evaluated eagerly, which calls
// `runChainRemaining` and spawns orphan chain steps.
let finalized = false;

const finalizeAndContinue = (result: SingleResult, job: Job) => {
	// Re-entrancy guard. If we already resolved (e.g. via
	// the watchdog timer that fired a second freeze), the
	// close handler firing for a SIGKILL'd proc must not
	// spawn anything. `resolve()` is a no-op on the second
	// call, but its argument is evaluated eagerly — that
	// was the R1 orphan-chain-step bug.
	if (finalized) return;
	finalized = true;
	disarmWatchdog();
	unregisterSuspension(susp.id);

	// If the proc was killed by handleKill, we still want
	// to resolve cleanly with the partial transcript (the
	// caller already got its kill-text response from
	// handleKill). Reaching here from the close handler
	// after a kill means the kill-path response is
	// already returned; the late resolve is harmless but
	// we DO want to skip the chain/parallel continuation
	// to avoid orphan steps. The `susp.cancelled` flag
	// handles that.
	if (susp.cancelled) {
		resolve({
			content: [
				{
					type: "text",
					text: getFinalOutput(result.messages) || "(no output)",
				},
			],
			details: makeDetails(resumeMode(job))([result]),
		});
		return;
	}

	if (job.kind === "single") {
		const isError = isFailedResult(result);
		const out = getFinalOutput(result.messages) || "(no output)";
		resolve({
			content: isError
				? [{ type: "text", text: `Agent ${result.stopReason || "failed"}: ${out}` }]
				: [{ type: "text", text: out }],
			details: makeDetails("single")([result]),
			isError,
		});
		return;
	}
	if (job.kind === "chain") {
		// Continue the chain from `job.index` using the partial
		// result we just resumed as step `job.index`.
		const allResults: SingleResult[] = [...job.results.map(liteToSingle), result];
		const previousOutput = getFinalOutput(result.messages);
		resolve(
			runChainRemaining(
				job.steps.slice(job.index + 1),
				job.index + 1,
				previousOutput,
				allResults,
				job.steps,
				ctx,
				signal,
				onUpdate,
				agents,
				allToolNames,
				agentScope,
				discovery,
				makeDetails,
				modelOverride,
			),
		);
		return;
	}
	if (job.kind === "parallel") {
		// Rebuild a fully-ordered result array of length
		// `tasks.length` from the original task spec — NOT
		// from `completedResults` (which excludes the
		// suspended index and so is one slot short). For
		// every completed sibling we lift the lite back to
		// a `SingleResult`; the resumed `result` is dropped
		// into its original index verbatim.
		const merged: SingleResult[] = new Array(job.tasks.length);
		let sibCursor = 0;
		for (let i = 0; i < job.tasks.length; i++) {
			if (i === job.index) {
				merged[i] = result;
			} else {
				merged[i] = liteToSingle(job.completedResults[sibCursor]!);
				sibCursor++;
			}
		}
		const successCount = merged.filter((r) => !isFailedResult(r)).length;
		const summaries = merged.map((r) => {
			const output = truncateParallelOutput(getResultOutput(r));
			const status = isFailedResult(r)
				? `failed${r.stopReason && r.stopReason !== "end" ? ` (${r.stopReason})` : ""}`
				: "completed";
			return `### [${r.agent}] ${status}\n\n${output}`;
		});
		resolve({
			content: [
				{
					type: "text",
					text: `Parallel: ${successCount}/${merged.length} succeeded\n\n${summaries.join("\n\n---\n\n")}`,
				},
			],
			details: makeDetails("parallel")(merged),
		});
		return;
	}
};

