					text += `\n${theme.fg("muted", `idleMs: ${susp.idleMs}`)}`;
					text += `\n${theme.fg("muted", `runningCommand: ${susp.runningCommand ?? "(none)"}`)}`;
					for (const e of susp.tail) {
						const prefix =
							e.kind === "assistant_text"
