/**
 * Subagent Tool - Delegate tasks to specialized agents
 *
 * Spawns a separate `pi` process for each subagent invocation,
 * giving it an isolated context window.
 *
 * Supports three modes:
 *   - Single: { agent: "name", task: "..." }
 *   - Parallel: { tasks: [{ agent: "name", task: "..." }, ...] }
 *   - Chain: { chain: [{ agent: "name", task: "... {previous} ..." }, ...] }
 *
 * Uses JSON mode to capture structured output from subagents.
 *
 * Idle arbitration protocol (added by the watchdog)
 * -------------------------------------------------
 * When a sub-process stops producing stdout / stderr for too long
 * (default 600s, see `IDLE_TIMEOUT_MS`), the parent freezes the
 * entire process group with SIGSTOP and returns a fact-only snapshot
 * to the calling LLM. The parent then decides what to do via a
 * follow-up subagent call carrying one of three mutually-exclusive
 * parameters:
 *
 *   - `resume: <suspensionId>` — thaw the process group, re-arm the
 *     watchdog, and continue collecting events until the process
 *     exits. Returns the final transcript.
 *   - `kill:   <suspensionId>` — thaw, then SIGKILL the entire
 *     process group, and return the partial transcript as a failed
 *     result.
 *   - `inspect: { id: <suspensionId>, lines?: number }` — return a
 *     larger tail of stdout/stderr events without touching the
 *     frozen process. Pure read.
 *
 * The full contract is documented in the `description` string passed
 * to `registerTool` so the LLM sees it without reading source.
 */

import { spawn } from "node:child_process";
import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import type { AgentToolResult } from "@earendil-works/pi-agent-core";
import type { Message } from "@earendil-works/pi-ai";
import { StringEnum } from "@earendil-works/pi-ai";
import {
	CONFIG_DIR_NAME,
	type ExtensionAPI,
	getAgentDir,
	getMarkdownTheme,
	loadSkills,
	withFileMutationQueue,
} from "@earendil-works/pi-coding-agent";
import { Container, Markdown, Spacer, Text } from "@earendil-works/pi-tui";
import { Type } from "typebox";
import { type AgentConfig, type AgentScope, discoverAgents } from "./agents.ts";
import {
	type InFlightToolCall,
	type Job,
	type JobKind,
	type SingleResultLite,
	type Suspension,
	type SuspensionId,
	attachSignalListener,
	detachAbortListener,
	extractInFlight,
	freezeProcessGroup,
	getAllSuspensions,
	getSuspension,
	isPosixSuspendSupported,
	killProcessGroup,
	newSuspensionId,
	reAttachAbortListener,
	registerSuspension,
	summarizeTail,
	thawProcessGroup,
	unregisterSuspension,
} from "./suspensions.ts";

const MAX_PARALLEL_TASKS = 8;
const MAX_CONCURRENCY = 4;
const COLLAPSED_ITEM_COUNT = 10;
const PER_TASK_OUTPUT_CAP = 50 * 1024;

/**
 * Idle watchdog timeout in milliseconds. 600s = 10 minutes. Tuned to
 * sit comfortably above the bash-guard default of 300s (5 minutes) so
 * that any command whose own timeout fires will produce a stderr /
 * stdout event long before the watchdog triggers — preventing false
 * positives on perfectly healthy long commands.
 *
 * Override via the `SUBAGENT_IDLE_TIMEOUT_MS` environment variable for
 * tighter test loops. Non-numeric / non-positive values fall back to
 * the default.
 */
const DEFAULT_IDLE_TIMEOUT_MS = 600_000;
const ENV_IDLE_TIMEOUT = "SUBAGENT_IDLE_TIMEOUT_MS";

function resolveIdleTimeoutMs(): number {
	const raw = process.env[ENV_IDLE_TIMEOUT];
	if (raw === undefined || raw === null || raw === "") return DEFAULT_IDLE_TIMEOUT_MS;
	const n = Number(raw);
	if (!Number.isFinite(n) || n <= 0) return DEFAULT_IDLE_TIMEOUT_MS;
	return n;
}

/** Default number of tail events included in the `idle_suspended` snapshot. */
const DEFAULT_TAIL_LINES = 10;
/** Default number of tail events returned by `inspect` when caller omits `lines`. */
const DEFAULT_INSPECT_LINES = 50;

function formatTokens(count: number): string {
	if (count < 1000) return count.toString();
	if (count < 10000) return `${(count / 1000).toFixed(1)}k`;
	if (count < 1000000) return `${Math.round(count / 1000)}k`;
	return `${(count / 1000000).toFixed(1)}M`;
}

function formatUsageStats(
	usage: {
		input: number;
		output: number;
		cacheRead: number;
		cacheWrite: number;
		cost: number;
		contextTokens?: number;
		turns?: number;
	},
	model?: string,
): string {
	const parts: string[] = [];
	if (usage.turns) parts.push(`${usage.turns} turn${usage.turns > 1 ? "s" : ""}`);
	if (usage.input) parts.push(`↑${formatTokens(usage.input)}`);
	if (usage.output) parts.push(`↓${formatTokens(usage.output)}`);
	if (usage.cacheRead) parts.push(`R${formatTokens(usage.cacheRead)}`);
	if (usage.cacheWrite) parts.push(`W${formatTokens(usage.cacheWrite)}`);
	if (usage.cost) parts.push(`$${usage.cost.toFixed(4)}`);
	if (usage.contextTokens && usage.contextTokens > 0) {
		parts.push(`ctx:${formatTokens(usage.contextTokens)}`);
	}
	if (model) parts.push(model);
	return parts.join(" ");
}

function formatToolCall(
	toolName: string,
	args: Record<string, unknown>,
	themeFg: (color: any, text: string) => string,
): string {
	const shortenPath = (p: string) => {
		const home = os.homedir();
		return p.startsWith(home) ? `~${p.slice(home.length)}` : p;
	};

	switch (toolName) {
		case "bash": {
			const command = (args.command as string) || "...";
			const preview = command.length > 60 ? `${command.slice(0, 60)}...` : command;
			return themeFg("muted", "$ ") + themeFg("toolOutput", preview);
		}
		case "read": {
			const rawPath = (args.file_path || args.path || "...") as string;
			const filePath = shortenPath(rawPath);
			const offset = args.offset as number | undefined;
			const limit = args.limit as number | undefined;
			let text = themeFg("accent", filePath);
			if (offset !== undefined || limit !== undefined) {
				const startLine = offset ?? 1;
				const endLine = limit !== undefined ? startLine + limit - 1 : "";
				text += themeFg("warning", `:${startLine}${endLine ? `-${endLine}` : ""}`);
			}
			return themeFg("muted", "read ") + text;
		}
		case "write": {
			const rawPath = (args.file_path || args.path || "...") as string;
			const filePath = shortenPath(rawPath);
			const content = (args.content || "") as string;
			const lines = content.split("\n").length;
			let text = themeFg("muted", "write ") + themeFg("accent", filePath);
			if (lines > 1) text += themeFg("dim", ` (${lines} lines)`);
			return text;
		}
		case "edit": {
			const rawPath = (args.file_path || args.path || "...") as string;
			return themeFg("muted", "edit ") + themeFg("accent", shortenPath(rawPath));
		}
		case "ls": {
			const rawPath = (args.path || ".") as string;
			return themeFg("muted", "ls ") + themeFg("accent", shortenPath(rawPath));
		}
		case "find": {
			const pattern = (args.pattern || "*") as string;
			const rawPath = (args.path || ".") as string;
			return themeFg("muted", "find ") + themeFg("accent", pattern) + themeFg("dim", ` in ${shortenPath(rawPath)}`);
		}
		case "grep": {
			const pattern = (args.pattern || "") as string;
			const rawPath = (args.path || ".") as string;
			return (
				themeFg("muted", "grep ") +
				themeFg("accent", `/${pattern}/`) +
				themeFg("dim", ` in ${shortenPath(rawPath)}`)
			);
		}
		default: {
			const argsStr = JSON.stringify(args);
			const preview = argsStr.length > 50 ? `${argsStr.slice(0, 50)}...` : argsStr;
			return themeFg("accent", toolName) + themeFg("dim", ` ${preview}`);
		}
	}
}

interface UsageStats {
	input: number;
	output: number;
	cacheRead: number;
	cacheWrite: number;
	cost: number;
	contextTokens: number;
	turns: number;
}

interface SingleResult {
	agent: string;
	agentSource: "user" | "project" | "unknown";
	task: string;
	exitCode: number;
	messages: Message[];
	stderr: string;
	usage: UsageStats;
	model?: string;
	stopReason?: string;
	errorMessage?: string;
	step?: number;
}

interface SubagentDetails {
	mode: "single" | "parallel" | "chain";
	agentScope: AgentScope;
	projectAgentsDir: string | null;
	results: SingleResult[];
	/**
	 * One snapshot per suspended sub-process. Empty for normal
	 * (non-suspended) results — the factory below guarantees
	 * `suspensions: []` rather than leaving the field undefined so
	 * `renderResult` (which reads `.suspensions.length` /
	 * `.suspensions[i]`) never has to do an existence check on
	 * every render. The defensive `?.` it keeps is purely an
	 * extra-paranoid belt-and-braces guard for tool results that
	 * might have come from a future codepath.
	 */
	suspensions: SuspendedSnapshot["suspensions"];
}

interface SuspendedSnapshot {
	mode: "single" | "parallel" | "chain";
	results: SingleResult[];
	/** One snapshot per suspended sub-process, identified by
	 *  `suspensionId`. Parallel mode may have several; single/chain
	 *  at most one. */
	suspensions: Array<{
		suspensionId: string;
		idleMs: number;
		runningCommand: string | null;
		requestedTimeout: number | null;
		tail: ReturnType<typeof summarizeTail>;
	}>;
}

function getFinalOutput(messages: Message[]): string {
	for (let i = messages.length - 1; i >= 0; i--) {
		const msg = messages[i];
		if (msg.role === "assistant") {
			for (const part of msg.content) {
				if (part.type === "text") return part.text;
			}
		}
	}
	return "";
}

function isFailedResult(result: SingleResult): boolean {
	return result.exitCode !== 0 || result.stopReason === "error" || result.stopReason === "aborted";
}

function getResultOutput(result: SingleResult): string {
	if (isFailedResult(result)) {
		return result.errorMessage || result.stderr || getFinalOutput(result.messages) || "(no output)";
	}
	return getFinalOutput(result.messages) || "(no output)";
}

function truncateParallelOutput(output: string): string {
	const byteLength = Buffer.byteLength(output, "utf8");
	if (byteLength <= PER_TASK_OUTPUT_CAP) return output;

	let truncated = output.slice(0, PER_TASK_OUTPUT_CAP);
	while (Buffer.byteLength(truncated, "utf8") > PER_TASK_OUTPUT_CAP) {
		truncated = truncated.slice(0, -1);
	}
	return `${truncated}\n\n[Output truncated: ${byteLength - Buffer.byteLength(truncated, "utf8")} bytes omitted. Full output preserved in tool details.]`;
}

type DisplayItem = { type: "text"; text: string } | { type: "toolCall"; name: string; args: Record<string, any> };

function getDisplayItems(messages: Message[]): DisplayItem[] {
	const items: DisplayItem[] = [];
	for (const msg of messages) {
		if (msg.role === "assistant") {
			for (const part of msg.content) {
				if (part.type === "text") items.push({ type: "text", text: part.text });
				else if (part.type === "toolCall") items.push({ type: "toolCall", name: part.name, args: part.arguments });
			}
		}
	}
	return items;
}

async function mapWithConcurrencyLimit<TIn, TOut>(
	items: TIn[],
	concurrency: number,
	fn: (item: TIn, index: number) => Promise<TOut>,
): Promise<TOut[]> {
	if (items.length === 0) return [];
	const limit = Math.max(1, Math.min(concurrency, items.length));
	const results: TOut[] = new Array(items.length);
	let nextIndex = 0;
	const workers = new Array(limit).fill(null).map(async () => {
		while (true) {
			const current = nextIndex++;
			if (current >= items.length) return;
			results[current] = await fn(items[current], current);
		}
	});
	await Promise.all(workers);
	return results;
}

async function writePromptToTempFile(agentName: string, prompt: string): Promise<{ dir: string; filePath: string }> {
	const tmpDir = await fs.promises.mkdtemp(path.join(os.tmpdir(), "pi-subagent-"));
	const safeName = agentName.replace(/[^\w.-]+/g, "_");
	const filePath = path.join(tmpDir, `prompt-${safeName}.md`);
	await withFileMutationQueue(filePath, async () => {
		await fs.promises.writeFile(filePath, prompt, { encoding: "utf-8", mode: 0o600 });
	});
	return { dir: tmpDir, filePath };
}

function getPiInvocation(args: string[]): { command: string; args: string[] } {
	const currentScript = process.argv[1];
	const isBunVirtualScript = currentScript?.startsWith("/$bunfs/root/");
	if (currentScript && !isBunVirtualScript && fs.existsSync(currentScript)) {
		return { command: process.execPath, args: [currentScript, ...args] };
	}

	const execName = path.basename(process.execPath).toLowerCase();
	const isGenericRuntime = /^(node|bun)(\.exe)?$/.test(execName);
	if (!isGenericRuntime) {
		return { command: process.execPath, args };
	}

	return { command: "pi", args };
}

/**
 * Resolve an agent's skill whitelist to concrete skill file paths.
 *
 * Strict whitelist model: the caller always passes `--no-skills` to the child
 * process, so only the skills listed here are visible. Entries may be skill
 * names (resolved against pi's default `.pi` skill discovery for the child's
 * cwd) or filesystem paths (relative to cwd, `~`-prefixed, or absolute).
 *
 * Returns `paths` to feed to `--skill`, plus `missing` (unresolved entries) and
 * `available` (all discovered skill names, for error messages).
 */
function resolveSkillPaths(
	agentSkills: string[],
	cwd: string,
): { paths: string[]; missing: string[]; available: string[] } {
	const result = loadSkills({
		cwd,
		agentDir: getAgentDir(),
		skillPaths: [],
		includeDefaults: true,
	});

	const byName = new Map<string, string>();
	for (const skill of result.skills) byName.set(skill.name, skill.filePath);
	const available = Array.from(byName.keys()).sort();

	const paths: string[] = [];
	const missing: string[] = [];
	const seen = new Set<string>();

	for (const entry of agentSkills) {
		const trimmed = entry.trim();
		if (!trimmed) continue;

		const looksLikePath = trimmed.includes(path.sep) || trimmed.startsWith(".") || trimmed.startsWith("~");
		let resolved: string | undefined;
		if (looksLikePath) {
			const expanded = trimmed.startsWith("~") ? path.join(os.homedir(), trimmed.slice(1)) : trimmed;
			const abs = path.isAbsolute(expanded) ? expanded : path.resolve(cwd, expanded);
			if (fs.existsSync(abs)) resolved = abs;
		} else {
			resolved = byName.get(trimmed);
		}

		if (!resolved) {
			missing.push(trimmed);
		} else if (!seen.has(resolved)) {
			seen.add(resolved);
			paths.push(resolved);
		}
	}

	return { paths, missing, available };
}

/**
 * Resolve an agent's tool configuration to a concrete tool list.
 *
 * - If neither `tools` nor `toolsDeny` is set → returns all tools
 * - `tools` entries ending with `*` are expanded as prefix wildcards against `allToolNames`
 * - When `tools` is set → start from the whitelist, then filter out `toolsDeny`
 * - When only `toolsDeny` is set → start from all tools, filter out denied ones
 * - Always filters out `"subagent"` to prevent recursive delegation through child agents
 *
 * Returns a concrete `string[]` (never undefined) so the caller can distinguish
 * "empty whitelist" (deny everything) from "no whitelist at all" (allow all).
 */
function resolveTools(agent: AgentConfig, allToolNames: string[]): string[] {
	let resolved: string[];

	if (agent.tools) {
		// Whitelist with wildcard expansion
		resolved = [];
		for (const tool of agent.tools) {
			if (tool.endsWith("*")) {
				const prefix = tool.slice(0, -1);
				const matches = allToolNames.filter((t) => t.startsWith(prefix));
				resolved.push(...matches);
			} else {
				resolved.push(tool);
			}
		}
		// Deduplicate
		resolved = [...new Set(resolved)];
	} else {
		// No whitelist, start from all tools
		resolved = [...allToolNames];
	}

	// Apply explicit deny list from frontmatter
	if (agent.toolsDeny && agent.toolsDeny.length > 0) {
		resolved = resolved.filter((t) => !agent.toolsDeny!.includes(t));
	}

	// Always deny subagent to prevent recursive delegation
	resolved = resolved.filter((t) => t !== "subagent");

	return resolved;
}

type OnUpdateCallback = (partial: AgentToolResult<SubagentDetails | SuspendedSnapshot>) => void;

/* -------------------------------------------------------------------------- */
/*                     SingleResult <-> SingleResultLite                      */
/* -------------------------------------------------------------------------- */

function liteToSingle(lite: SingleResultLite): SingleResult {
	return {
		agent: lite.agent,
		agentSource: lite.agentSource,
		task: lite.task,
		exitCode: lite.exitCode,
		messages: lite.messages,
		stderr: lite.stderr,
		usage: lite.usage,
		model: lite.model,
		stopReason: lite.stopReason,
		errorMessage: lite.errorMessage,
		step: lite.step,
	};
}

function singleToLite(r: SingleResult): SingleResultLite {
	return {
		agent: r.agent,
		agentSource: r.agentSource,
		task: r.task,
		exitCode: r.exitCode,
		messages: r.messages,
		stderr: r.stderr,
		usage: r.usage,
		model: r.model,
		stopReason: r.stopReason,
		errorMessage: r.errorMessage,
		step: r.step,
	};
}

/* -------------------------------------------------------------------------- */
/*                              runSingleAgent                                */
/* -------------------------------------------------------------------------- */

/**
 * Union returned from `runSingleAgent`. Either the process exited and
 * we have a normal transcript, OR the idle watchdog froze it and we
 * have a suspension id to refer back to.
 *
 * `suspended` means "tool call returns early with a snapshot; caller
 * must invoke `resume`/`kill`/`inspect` later to finish the job".
 */
type SingleRunOutcome =
	| { kind: "exit"; result: SingleResult }
	| { kind: "suspended"; id: SuspensionId; snapshot: SingleResult; lastEventAtMs: number };

/**
 * Run a single sub-agent end-to-end and return either an exit or a
 * suspension.
 *
 * This is the workhorse for all three modes (single / chain / parallel).
 * Chain/parallel wrappers call it per step / per task; the watcher here
 * is identical for every invocation.
 *
 * Watchdog wiring
 * ---------------
 *   - Every NDJSON line we successfully parse from `stdout` resets the
 *     idle timer. A process that is "thinking" (sending `message_*`
 *     events) never trips the watchdog.
 *   - Every `stderr` chunk resets the timer too. Bash subprocesses
 *     often print progress to stderr.
 *   - On `close` or `error`, the timer is cleared (process is gone).
 *   - When the timer fires we:
 *       1. Freeze the whole process group via SIGSTOP (POSIX) or, on
 *          win32 where SIGSTOP doesn't exist, immediately SIGKILL it
 *          and return as a failed exit (no suspension registered — see
 *          the win32 note below).
 *       2. Snapshot the partial transcript (the `messages` and `stderr`
 *          accumulated so far) and bundle it with the resume-context
 *          (`Job`) the parent caller passed in.
 *       3. Detach the abort handler so a user Ctrl+C won't try to
 *          SIGTERM a stopped process (SIGTERM is queued, not delivered,
 *          until SIGCONT — which would race with our resume/kill).
 *       4. Register the Suspension, then resolve with kind="suspended".
 *
 * Win32 fallback (no SIGSTOP)
 * ---------------------------
 * Windows has no job-freeze primitive in the POSIX sense. We could
 * `SuspendThread` but that only freezes one thread inside the sub-`pi`
 * process — its children (bash, deadlock-grandchildren) keep running,
 * which defeats the point. So on win32 the watchdog simply
 * `killProcessGroup`s the child, marks the run as a failed exit
 * (exitCode=-1, stopReason="aborted"), and returns. No suspension is
 * registered and no arbitration is offered. This is documented in the
 * watchdog comment so future readers know it is a deliberate decision,
 * not an oversight.
 */
async function runSingleAgent(
	defaultCwd: string,
	agents: AgentConfig[],
	agentName: string,
	task: string,
	cwd: string | undefined,
	step: number | undefined,
	signal: AbortSignal | undefined,
	onUpdate: OnUpdateCallback | undefined,
	makeDetails: (results: SingleResult[], suspensions?: SuspendedSnapshot["suspensions"]) => SubagentDetails | SuspendedSnapshot,
	allToolNames: string[],
	modelOverride: string | undefined,
	job: Job,
	stepNumber: number,
): Promise<SingleRunOutcome> {
	const agent = agents.find((a) => a.name === agentName);

	if (!agent) {
		const available = agents.map((a) => `"${a.name}"`).join(", ") || "none";
		const errResult: SingleResult = {
			agent: agentName,
			agentSource: "unknown",
			task,
			exitCode: 1,
			messages: [],
			stderr: `Unknown agent: "${agentName}". Available agents: ${available}.`,
			usage: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, cost: 0, contextTokens: 0, turns: 0 },
			step,
		};
		return { kind: "exit", result: errResult };
	}

	const effectiveCwd = cwd ?? defaultCwd;
	const effectiveModel = modelOverride ?? agent.model;
	const idleTimeoutMs = resolveIdleTimeoutMs();

	const args: string[] = ["--mode", "json", "-p", "--no-session"];
	if (effectiveModel) args.push("--model", effectiveModel);
	const resolvedTools = resolveTools(agent, allToolNames);
	if (resolvedTools.length > 0) {
		args.push("--tools", resolvedTools.join(","));
	} else {
		args.push("--no-tools");
	}

	// Strict skill whitelist: deny all skills by default. Only skills declared on
	// the agent are exposed to the child, resolved to concrete paths via `--skill`.
	args.push("--no-skills");
	if (agent.skills && agent.skills.length > 0) {
		const { paths, missing, available } = resolveSkillPaths(agent.skills, effectiveCwd);
		if (missing.length > 0) {
			const avail = available.length > 0 ? available.join(", ") : "none";
			const errResult: SingleResult = {
				agent: agentName,
				agentSource: agent.source,
				task,
				exitCode: 1,
				messages: [],
				stderr: `Unknown skills for agent "${agentName}": ${missing.map((m) => `"${m}"`).join(", ")}. Available skills: ${avail}.`,
				usage: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, cost: 0, contextTokens: 0, turns: 0 },
				step,
			};
			return { kind: "exit", result: errResult };
		}
		for (const p of paths) args.push("--skill", p);
	}

	let tmpPromptDir: string | null = null;
	let tmpPromptPath: string | null = null;

	const currentResult: SingleResult = {
		agent: agentName,
		agentSource: agent.source,
		task,
		exitCode: 0,
		messages: [],
		stderr: "",
		usage: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, cost: 0, contextTokens: 0, turns: 0 },
		model: effectiveModel,
		step,
	};

	const emitUpdate = () => {
		if (onUpdate) {
			onUpdate({
				content: [{ type: "text", text: getFinalOutput(currentResult.messages) || "(running...)" }],
				details: makeDetails([currentResult]),
			});
		}
	};

	try {
		if (agent.systemPrompt.trim()) {
			const tmp = await writePromptToTempFile(agent.name, agent.systemPrompt);
			tmpPromptDir = tmp.dir;
			tmpPromptPath = tmp.filePath;
			args.push("--append-system-prompt", tmpPromptPath);
		}

		args.push(`Task: ${task}`);
		let wasAborted = false;

		// Last timestamp we saw *any* activity on the sub-process. Used
		// both to reset the idle watchdog and to compute `idleMs` in the
		// suspension snapshot (so the LLM can tell whether the freeze is
		// "just hit 600s" or "has been dead for hours").
		let lastEventAtMs = Date.now();

		const outcome = await new Promise<SingleRunOutcome>((resolve) => {
			const invocation = getPiInvocation(args);
			const invocationStr = `${invocation.command} ${invocation.args.join(" ")}`;
			// `detached: true` puts the child in its own process group
			// (its pgid equals its pid). Required for SIGSTOP / SIGKILL
			// to affect the bash subprocesses it spawns — without it,
			// `process.kill(-pid, ...)` would target *our* process group
			// and freeze/kill the whole parent.
			const proc = spawn(invocation.command, invocation.args, {
				cwd: effectiveCwd,
				shell: false,
				stdio: ["ignore", "pipe", "pipe"],
				detached: true,
			});
			let buffer = "";

			// Idle watchdog. Recreated (cleared + re-armed) on every
			// stdout line and every stderr chunk. `idleTimer` is `null`
			// between events, never a phantom reference.
			//
			// `suspended` flips to true the moment we register a
			// Suspension for this run. After that, ALL event handlers
			// (data / close / error / timer) short-circuit so the
			// original listeners do not race against the resumed-leg
			// listeners added in `handleResume`. Without this flag, a
			// continued stdout trickle between freeze and resume keeps
			// re-arming the watchdog and (on second fire) creates a
			// duplicate Suspension that points at the same proc.
			let suspended = false;
			let idleTimer: NodeJS.Timeout | null = null;
			const armWatchdog = () => {
				if (suspended) return;
				if (idleTimer) clearTimeout(idleTimer);
				idleTimer = setTimeout(() => {
					idleTimer = null;
					// Race guard: if the proc already exited cleanly,
					// `proc.on("close")` already disarmed the timer in
					// its callback, but `clearTimeout` is a no-op once
					// the timeout has fired. Node delivers timer +
					// close events in implementation-defined order, so
					// it is possible we are racing the close handler.
					// Treat "process is already dead" as authoritative
					// and bail before we (a) freeze a corpse (ESRCH,
					// falling through to the win32 branch) and (b)
					// overwrite a successful `stopReason` with
					// `aborted`.
					if (proc.exitCode !== null) {
						disarmWatchdog();
						return;
					}
					// Watchdog fired. Freeze the process group and resolve
					// with a suspension id, OR (on win32) immediately
					// SIGKILL the group and resolve as a failed exit.
					const frozen = freezeProcessGroup(proc);
					if (!frozen) {
						// Win32 branch. SIGSTOP doesn't exist; we cannot
						// pause a process group from userland without
						// undocumented Win32 APIs that would also miss
						// the bash grandchildren. Just kill it. The
						// partial transcript is preserved as a failed
						// exit so the parent LLM still has context for
						// its next move.
						currentResult.exitCode = -1;
						currentResult.stopReason = "aborted";
						wasAborted = true;
						killProcessGroup(proc);
						resolve({ kind: "exit", result: { ...currentResult } });
						return;
					}

					// POSIX branch: SIGSTOP succeeded. Register the
					// suspension so the parent can resume / kill /
					// inspect.
					const suspendedAtMs = Date.now();
					const id = newSuspensionId();
					const inFlight: InFlightToolCall | null = extractInFlight(currentResult.messages);
					const partialLite: SingleResultLite = {
						...currentResult,
						// Step number is the chain-step or parallel-index
						// (1-based for chain, undefined for single).
						step: stepNumber,
					};
					const suspension: Suspension = {
						id,
						proc,
						inFlight,
						messages: currentResult.messages,
						stderr: currentResult.stderr,
						invocation: invocationStr,
						job,
						partialResult: partialLite,
						lastEventAtMs,
						originalSignal: signal,
						activeAbortHandler: abortHandler,
						cancelled: false,
					};
					// Detach abort handler BEFORE registering. If the
					// user hits Ctrl+C right after the freeze fires,
					// we don't want the queued SIGTERM racing with the
					// LLM's `kill` decision (SIGTERM is not delivered
					// to a stopped process until SIGCONT, so it would
					// surprise us when we resume).
					detachAbortListener(signal, abortHandler);
					suspended = true;
					suspension.activeAbortHandler = null;
					registerSuspension(suspension);
					const snapshotResult: SingleResult = {
						...currentResult,
						step: stepNumber,
					};
					resolve({
						kind: "suspended",
						id,
						snapshot: snapshotResult,
						lastEventAtMs,
					});
					// `suspendedAtMs` is captured for the suspension's
						// internal bookkeeping only; the `idleMs` exposed
						// to the caller is computed from `lastEventAtMs`.
						void suspendedAtMs;
				}, idleTimeoutMs);
			};

			const disarmWatchdog = () => {
				if (idleTimer) {
					clearTimeout(idleTimer);
					idleTimer = null;
				}
			};

			const processLine = (line: string) => {
				if (!line.trim()) return;
				let event: any;
				try {
					event = JSON.parse(line);
				} catch {
					return;
				}

				if (event.type === "message_end" && event.message) {
					const msg = event.message as Message;
					currentResult.messages.push(msg);

					if (msg.role === "assistant") {
						currentResult.usage.turns++;
						const usage = msg.usage;
						if (usage) {
							currentResult.usage.input += usage.input || 0;
							currentResult.usage.output += usage.output || 0;
							currentResult.usage.cacheRead += usage.cacheRead || 0;
							currentResult.usage.cacheWrite += usage.cacheWrite || 0;
							currentResult.usage.cost += usage.cost?.total || 0;
							currentResult.usage.contextTokens = usage.totalTokens || 0;
						}
						if (!currentResult.model && msg.model) currentResult.model = msg.model;
						if (msg.stopReason) currentResult.stopReason = msg.stopReason;
						if (msg.errorMessage) currentResult.errorMessage = msg.errorMessage;
					}
					emitUpdate();
				}

				if (event.type === "tool_result_end" && event.message) {
					currentResult.messages.push(event.message as Message);
					emitUpdate();
				}
			};

			proc.stdout.on("data", (data) => {
				if (suspended) return;
				lastEventAtMs = Date.now();
				armWatchdog();
				buffer += data.toString();
				const lines = buffer.split("\n");
				buffer = lines.pop() || "";
				for (const line of lines) processLine(line);
			});

			proc.stderr.on("data", (data) => {
				if (suspended) return;
				lastEventAtMs = Date.now();
				armWatchdog();
				currentResult.stderr += data.toString();
			});

			proc.on("close", (code) => {
				if (suspended) return;
				disarmWatchdog();
				if (buffer.trim()) processLine(buffer);
				currentResult.exitCode = code ?? 0;
				resolve({ kind: "exit", result: { ...currentResult } });
			});

			proc.on("error", () => {
				if (suspended) return;
				disarmWatchdog();
				currentResult.exitCode = 1;
				resolve({ kind: "exit", result: { ...currentResult } });
			});

			// Abort handling. The handler is detached on suspend and
			// re-attached on resume, so the registry (not a closure)
			// decides whether a given Ctrl+C should reach the process.
			const abortHandler = (() => {
				const h = () => {
					// Defensive: if we already suspended or the proc
					// died, do nothing. SIGTERM'ing a stopped process
					// is a no-op until SIGCONT, and SIGTERM'ing a dead
					// process throws ESRCH.
					if (proc.exitCode !== null) return;
					if (suspended) return;
					wasAborted = true;
					try {
						if (proc.pid) process.kill(-proc.pid, "SIGTERM");
					} catch {
						/* swallow */
					}
					setTimeout(() => {
						if (!proc.killed) killProcessGroup(proc);
					}, 5000);
				};
				return h;
			})();
			// Wire it up. `attachSignalListener` is also called on
			// resume to re-arm.
			//
			// We pass `() => suspended` so the underlying helper
			// receives the SAME flag this closure reads. After
			// `detachAbortListener` removes this handler on freeze,
			// the flag should no longer matter (no listeners), but
			// it guards against double-attaches during the brief
			// window between `set suspended = true` and the remove.
			if (signal) {
				if (signal.aborted) abortHandler();
				else signal.addEventListener("abort", abortHandler, { once: true });
			}

			// Prime the watchdog immediately so a process that never
			// produces a single byte still triggers after the timeout.
			armWatchdog();
		});

		if (outcome.kind === "exit") {
			if (wasAborted && outcome.result.stopReason !== "aborted") {
				outcome.result.stopReason = "aborted";
			}
			return outcome;
		}
		return outcome;
	} finally {
		if (tmpPromptPath)
			try {
				fs.unlinkSync(tmpPromptPath);
			} catch {
				/* ignore */
			}
		if (tmpPromptDir)
			try {
				fs.rmdirSync(tmpPromptDir);
			} catch {
				/* ignore */
			}
	}
}

const TaskItem = Type.Object({
	agent: Type.String({ description: "Name of the agent to invoke" }),
	task: Type.String({ description: "Task to delegate to the agent" }),
	cwd: Type.Optional(Type.String({ description: "Working directory for the agent process" })),
	model: Type.Optional(Type.String({ description: "Override the agent's frontmatter model for this task" })),
});

const ChainItem = Type.Object({
	agent: Type.String({ description: "Name of the agent to invoke" }),
	task: Type.String({ description: "Task with optional {previous} placeholder for prior output" }),
	cwd: Type.Optional(Type.String({ description: "Working directory for the agent process" })),
	model: Type.Optional(Type.String({ description: "Override the agent's frontmatter model for this step" })),
});

const AgentScopeSchema = StringEnum(["user", "project", "both"] as const, {
	description: 'Which agent directories to use. Default: "both" (user + project).',
	default: "both",
});

const InspectParams = Type.Object({
	id: Type.String({ description: "Suspension id to inspect" }),
	lines: Type.Optional(Type.Number({ description: `Number of tail lines to return (default ${DEFAULT_INSPECT_LINES})`, default: DEFAULT_INSPECT_LINES })),
});

const SubagentParams = Type.Object({
	agent: Type.Optional(Type.String({ description: "Name of the agent to invoke (for single mode)" })),
	task: Type.Optional(Type.String({ description: "Task to delegate (for single mode)" })),
	tasks: Type.Optional(Type.Array(TaskItem, { description: "Array of {agent, task} for parallel execution" })),
	chain: Type.Optional(Type.Array(ChainItem, { description: "Array of {agent, task} for sequential execution" })),
	agentScope: Type.Optional(AgentScopeSchema),
	cwd: Type.Optional(Type.String({ description: "Working directory for the agent process (single mode)" })),
	model: Type.Optional(Type.String({ description: "Override the agent's frontmatter model. Used directly in single mode; acts as the default for parallel/chain tasks that don't set their own `model`" })),
	resume: Type.Optional(Type.String({ description: "Suspension id to resume — thaws the frozen process group and continues collecting events" })),
	kill: Type.Optional(Type.String({ description: "Suspension id to kill — thaws the frozen process group, SIGKILLs it, returns the partial transcript" })),
	inspect: Type.Optional(InspectParams),
});

/* -------------------------------------------------------------------------- */
/*                              Tool description                               */
/* -------------------------------------------------------------------------- */

const SUBAGENT_DESCRIPTION = [
	"Delegate tasks to specialized subagents with isolated context.",
	"Modes: single (agent + task), parallel (tasks array), chain (sequential with {previous} placeholder).",
	`Loads agents from both ${path.join(getAgentDir(), "agents")} (user) and ${CONFIG_DIR_NAME}/agents (project). Project agents load without a confirmation prompt.`,
	"A `model` passed at runtime overrides the agent's frontmatter model (frontmatter is only the default). Top-level `model` applies in single mode and is the default for parallel/chain; per-item `model` overrides per-task.",
	"",
	"Idle arbitration protocol: a sub-process that produces no stdout/stderr for ~10 minutes is frozen via SIGSTOP (whole process group, including its bash subprocesses) and the tool call returns a snapshot with `status:\"idle_suspended\"`. To finish the job, call this tool again with one of three mutually-exclusive parameters:",
	"  - `resume: <suspensionId>` — thaw the process group, re-arm the watchdog, and continue collecting events until the process exits; returns the final transcript.",
	"  - `kill:   <suspensionId>` — thaw then SIGKILL the whole process group; returns the partial transcript as a failed result.",
	"  - `inspect: { id: <suspensionId>, lines?: number }` — return more tail lines of the frozen process without touching it.",
	"The snapshot exposes `suspensionId`, `idleMs`, `runningCommand` (the in-flight bash command, if any), `requestedTimeout` (the timeout the agent asked for), and a `tail` array of recent events.",
	"`resume` / `kill` / `inspect` cannot be combined with `agent` / `task` / `tasks` / `chain`; pick exactly one mode per call.",
].join(" ");

/* -------------------------------------------------------------------------- */
/*                              Arbitration helpers                           */
/* -------------------------------------------------------------------------- */

function buildSuspendedSnapshot(
	mode: "single" | "parallel" | "chain",
	suspensions: Array<{
		suspensionId: string;
		snapshot: SingleResult;
		lastEventAtMs: number;
	}>,
): SuspendedSnapshot["suspensions"] {
	const now = Date.now();
	return suspensions.map((s) => {
		const inFlight = extractInFlight(s.snapshot.messages);
		return {
			suspensionId: s.suspensionId,
			idleMs: now - s.lastEventAtMs,
			runningCommand: inFlight?.command ?? null,
			requestedTimeout: inFlight?.timeout ?? null,
			tail: summarizeTail(s.snapshot.messages, s.snapshot.stderr, DEFAULT_TAIL_LINES),
		};
	});
}

/* -------------------------------------------------------------------------- */
/*                                  Tool                                      */
/* -------------------------------------------------------------------------- */

export default function (pi: ExtensionAPI) {
	pi.registerTool({
		name: "subagent",
		label: "Subagent",
		description: SUBAGENT_DESCRIPTION,
		parameters: SubagentParams,

		async execute(_toolCallId, params, signal, onUpdate, ctx) {
			const agentScope: AgentScope = params.agentScope ?? "both";
			const discovery = discoverAgents(ctx.cwd, agentScope);
			const agents = discovery.agents;
			const allToolNames = pi.getAllTools().map((t) => t.name);

			const hasChain = (params.chain?.length ?? 0) > 0;
			const hasTasks = (params.tasks?.length ?? 0) > 0;
			const hasSingle = Boolean(params.agent && params.task);
			const hasResume = typeof params.resume === "string";
			const hasKill = typeof params.kill === "string";
			const hasInspect = params.inspect !== undefined;
			const arbitrationCount = Number(hasResume) + Number(hasKill) + Number(hasInspect);
			const modeCount = Number(hasChain) + Number(hasTasks) + Number(hasSingle);

			const available = agents.map((a) => `${a.name} (${a.source})`).join(", ") || "none";
			const makeDetails =
				(mode: "single" | "parallel" | "chain", suspensions?: SuspendedSnapshot["suspensions"]) =>
				(results: SingleResult[]): SubagentDetails | SuspendedSnapshot => {
					// Always set `suspensions` (possibly empty) so the
					// result-shape stays uniform. `renderResult` reads
					// `details.suspensions.length` directly; leaving the
					// field undefined makes every non-suspended result
					// throw a TypeError.
					return {
						mode,
						agentScope,
						projectAgentsDir: discovery.projectAgentsDir,
						results,
						suspensions: suspensions ?? [],
					};
				};

			// Arbitration parameters take precedence over execution modes
			// and are mutually exclusive with each other.
			if (arbitrationCount > 1) {
				return {
					content: [
						{
							type: "text",
							text: "Invalid parameters: `resume`, `kill`, and `inspect` are mutually exclusive. Pick exactly one.",
						},
					],
					details: makeDetails("single")([]),
				};
			}
			if (arbitrationCount === 1 && modeCount > 0) {
				return {
					content: [
						{
							type: "text",
							text: "Invalid parameters: arbitration parameters (`resume`/`kill`/`inspect`) cannot be combined with execution modes (`agent`/`task`/`tasks`/`chain`).",
						},
					],
					details: makeDetails("single")([]),
				};
			}

			if (hasResume) return handleResume(params.resume as string, signal, onUpdate, ctx, agents, allToolNames, agentScope, discovery, makeDetails, params.model);
			if (hasKill) return handleKill(params.kill as string, ctx, makeDetails);
			if (hasInspect) return handleInspect(params.inspect!, ctx, makeDetails);

			if (modeCount !== 1) {
				return {
					content: [
						{
							type: "text",
							text: `Invalid parameters. Provide exactly one mode.\nAvailable agents: ${available}`,
						},
					],
					details: makeDetails("single")([]),
				};
			}

			if (params.chain && params.chain.length > 0) {
				return runChain(params.chain, ctx, signal, onUpdate, agents, allToolNames, agentScope, discovery, makeDetails, params.model);
			}

			if (params.tasks && params.tasks.length > 0) {
				return runParallel(params.tasks, ctx, signal, onUpdate, agents, allToolNames, agentScope, discovery, makeDetails, params.model);
			}

			if (params.agent && params.task) {
				return runSingle(params.agent, params.task, params.cwd, ctx, signal, onUpdate, agents, allToolNames, agentScope, discovery, makeDetails, params.model);
			}

			return {
				content: [{ type: "text", text: `Invalid parameters. Available agents: ${available}` }],
				details: makeDetails("single")([]),
			};
		},

		renderCall(args, theme, _context) {
			const scope: AgentScope = args.agentScope ?? "both";
			if (args.resume) {
				return new Text(
					theme.fg("toolTitle", theme.bold("subagent ")) +
						theme.fg("accent", `resume`) +
						theme.fg("muted", ` ${args.resume}`),
					0,
					0,
				);
			}
			if (args.kill) {
				return new Text(
					theme.fg("toolTitle", theme.bold("subagent ")) +
						theme.fg("accent", `kill`) +
						theme.fg("muted", ` ${args.kill}`),
					0,
					0,
				);
			}
			if (args.inspect) {
				const lines = args.inspect.lines ?? DEFAULT_INSPECT_LINES;
				return new Text(
					theme.fg("toolTitle", theme.bold("subagent ")) +
						theme.fg("accent", `inspect`) +
						theme.fg("muted", ` ${args.inspect.id} (${lines} lines)`),
					0,
					0,
				);
			}
			if (args.chain && args.chain.length > 0) {
				let text =
					theme.fg("toolTitle", theme.bold("subagent ")) +
					theme.fg("accent", `chain (${args.chain.length} steps)`) +
					theme.fg("muted", ` [${scope}]`);
				for (let i = 0; i < Math.min(args.chain.length, 3); i++) {
					const step = args.chain[i];
					// Clean up {previous} placeholder for display
					const cleanTask = step.task.replace(/\{previous\}/g, "").trim();
					const preview = cleanTask.length > 40 ? `${cleanTask.slice(0, 40)}...` : cleanTask;
					text +=
						"\n  " +
						theme.fg("muted", `${i + 1}.`) +
						" " +
						theme.fg("accent", step.agent) +
						theme.fg("dim", ` ${preview}`);
				}
				if (args.chain.length > 3) text += `\n  ${theme.fg("muted", `... +${args.chain.length - 3} more`)}`;
				return new Text(text, 0, 0);
			}
			if (args.tasks && args.tasks.length > 0) {
				let text =
					theme.fg("toolTitle", theme.bold("subagent ")) +
					theme.fg("accent", `parallel (${args.tasks.length} tasks)`) +
					theme.fg("muted", ` [${scope}]`);
				for (const t of args.tasks.slice(0, 3)) {
					const preview = t.task.length > 40 ? `${t.task.slice(0, 40)}...` : t.task;
					text += `\n  ${theme.fg("accent", t.agent)}${theme.fg("dim", ` ${preview}`)}`;
				}
				if (args.tasks.length > 3) text += `\n  ${theme.fg("muted", `... +${args.tasks.length - 3} more`)}`;
				return new Text(text, 0, 0);
			}
			const agentName = args.agent || "...";
			const preview = args.task ? (args.task.length > 60 ? `${args.task.slice(0, 60)}...` : args.task) : "...";
			let text =
				theme.fg("toolTitle", theme.bold("subagent ")) +
				theme.fg("accent", agentName) +
				theme.fg("muted", ` [${scope}]`);
			text += `\n  ${theme.fg("dim", preview)}`;
			return new Text(text, 0, 0);
		},

		renderResult(result, { expanded }, theme, _context) {
			const details = result.details as SubagentDetails | SuspendedSnapshot | undefined;
			if (
				!details ||
				(details.results.length === 0 && (details.suspensions?.length ?? 0) === 0)
			) {
				const text = result.content[0];
				return new Text(text?.type === "text" ? text.text : "(no output)", 0, 0);
			}
			// Normalise: below we read `details.suspensions.length`
			// multiple times. If a future schema ever drops the
			// field, substitute an empty array locally rather than
			// crashing every render.
			const suspensions = details.suspensions ?? [];

			const mdTheme = getMarkdownTheme();

			const renderDisplayItems = (items: DisplayItem[], limit?: number) => {
				const toShow = limit ? items.slice(-limit) : items;
				const skipped = limit && items.length > limit ? items.length - limit : 0;
				let text = "";
				if (skipped > 0) text += theme.fg("muted", `... ${skipped} earlier items\n`);
				for (const item of toShow) {
					if (item.type === "text") {
						const preview = expanded ? item.text : item.text.split("\n").slice(0, 3).join("\n");
						text += `${theme.fg("toolOutput", preview)}\n`;
					} else {
						text += `${theme.fg("muted", "→ ") + formatToolCall(item.name, item.args, theme.fg.bind(theme))}\n`;
					}
				}
				return text.trimEnd();
			};

			// Render suspended snapshots with a distinct visual style so
			// the LLM can scan and notice them.
			if (suspensions.length > 0) {
				if (details.mode === "single" && details.results.length <= 1) {
					const r = details.results[0] ?? null;
					const susp = suspensions[0]!;
					const icon = theme.fg("warning", "⏸");
					const header = `${icon} ${theme.fg("toolTitle", theme.bold(r?.agent ?? "subagent"))} ${theme.fg("warning", "[idle_suspended]")}`;
					let text = header;
					text += `\n${theme.fg("muted", `suspensionId: ${susp.suspensionId}`)}`;
					text += `\n${theme.fg("muted", `idleMs: ${susp.idleMs}`)}`;
					text += `\n${theme.fg("muted", `runningCommand: ${susp.runningCommand ?? "(none)"}`)}`;
					if (susp.requestedTimeout !== null) text += `\n${theme.fg("muted", `requestedTimeout: ${susp.requestedTimeout}s`)}`;
					text += `\n${theme.fg("muted", "─── tail ───")}`;
					for (const e of susp.tail) {
						const prefix =
							e.kind === "assistant_text"
								? "text"
								: e.kind === "assistant_tool_call"
									? "tool"
									: e.kind === "stderr"
										? "stderr"
										: "result";
						text += `\n${theme.fg("dim", `[${prefix}] `)}${theme.fg("toolOutput", e.summary)}`;
					}
					text += `\n${theme.fg("muted", "(resume/kill/inspect with the suspensionId to proceed)")}`;
					return new Text(text, 0, 0);
				}

				// parallel / chain suspended — list each suspension alongside any completed results.
				let text = `${theme.fg("warning", "⏸")} ${theme.fg("toolTitle", theme.bold(`${details.mode} suspended`))}`;
				for (let i = 0; i < suspensions.length; i++) {
					const susp = suspensions[i]!;
					text += `\n\n${theme.fg("muted", `─── suspension ${i + 1} ───`)}`;
					text += `\n${theme.fg("muted", `id: ${susp.suspensionId}`)}`;
					text += `\n${theme.fg("muted", `idleMs: ${susp.idleMs}`)}`;
					text += `\n${theme.fg("muted", `runningCommand: ${susp.runningCommand ?? "(none)"}`)}`;
					for (const e of susp.tail) {
						const prefix =
							e.kind === "assistant_text"
								? "text"
								: e.kind === "assistant_tool_call"
									? "tool"
									: e.kind === "stderr"
										? "stderr"
										: "result";
						text += `\n${theme.fg("dim", `[${prefix}] `)}${theme.fg("toolOutput", e.summary)}`;
					}
				}
				return new Text(text, 0, 0);
			}

			if (details.mode === "single" && details.results.length === 1) {
				const r = details.results[0];
				const isError = isFailedResult(r);
				const icon = isError ? theme.fg("error", "✗") : theme.fg("success", "✓");
				const displayItems = getDisplayItems(r.messages);

				if (expanded) {
					const container = new Container();
					let header = `${icon} ${theme.fg("toolTitle", theme.bold(r.agent))}${theme.fg("muted", ` (${r.agentSource})`)}`;
					if (isError && r.stopReason) header += ` ${theme.fg("error", `[${r.stopReason}]`)}`;
					container.addChild(new Text(header, 0, 0));
					if (isError && r.errorMessage)
						container.addChild(new Text(theme.fg("error", `Error: ${r.errorMessage}`), 0, 0));
					container.addChild(new Spacer(1));
					container.addChild(new Text(theme.fg("muted", "─── Task ───"), 0, 0));
					container.addChild(new Text(theme.fg("dim", r.task), 0, 0));
					container.addChild(new Spacer(1));
					container.addChild(new Text(theme.fg("muted", "─── Output ───"), 0, 0));
					if (displayItems.length === 0) {
						container.addChild(new Text(theme.fg("muted", "(no output)"), 0, 0));
					} else {
						for (const item of displayItems) {
							if (item.type === "text") {
								if (item.text.trim()) {
									container.addChild(new Spacer(1));
									container.addChild(new Markdown(item.text.trim(), 0, 0, mdTheme));
								}
							} else {
								container.addChild(
									new Text(
										theme.fg("muted", "→ ") + formatToolCall(item.name, item.args, theme.fg.bind(theme)),
										0,
										0,
									),
								);
							}
						}
					}
					const usageStr = formatUsageStats(r.usage, r.model);
					if (usageStr) {
						container.addChild(new Spacer(1));
						container.addChild(new Text(theme.fg("dim", usageStr), 0, 0));
					}
					return container;
				}

				let text = `${icon} ${theme.fg("toolTitle", theme.bold(r.agent))}${theme.fg("muted", ` (${r.agentSource})`)}`;
				if (isError && r.stopReason) text += ` ${theme.fg("error", `[${r.stopReason}]`)}`;
				if (isError && r.errorMessage) text += `\n${theme.fg("error", `Error: ${r.errorMessage}`)}`;
				else if (displayItems.length === 0) text += `\n${theme.fg("muted", "(no output)")}`;
				else {
					text += `\n${renderDisplayItems(displayItems, COLLAPSED_ITEM_COUNT)}`;
					if (displayItems.length > COLLAPSED_ITEM_COUNT) text += `\n${theme.fg("muted", "(Ctrl+O to expand)")}`;
				}
				const usageStr = formatUsageStats(r.usage, r.model);
				if (usageStr) text += `\n${theme.fg("dim", usageStr)}`;
				return new Text(text, 0, 0);
			}

			const aggregateUsage = (results: SingleResult[]) => {
				const total = { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, cost: 0, turns: 0 };
				for (const r of results) {
					total.input += r.usage.input;
					total.output += r.usage.output;
					total.cacheRead += r.usage.cacheRead;
					total.cacheWrite += r.usage.cacheWrite;
					total.cost += r.usage.cost;
					total.turns += r.usage.turns;
				}
				return total;
			};

			if (details.mode === "chain") {
				const successCount = details.results.filter((r) => r.exitCode === 0).length;
				const icon = successCount === details.results.length ? theme.fg("success", "✓") : theme.fg("error", "✗");

				if (expanded) {
					const container = new Container();
					container.addChild(
						new Text(
							icon +
								" " +
								theme.fg("toolTitle", theme.bold("chain ")) +
								theme.fg("accent", `${successCount}/${details.results.length} steps`),
							0,
							0,
						),
					);

					for (const r of details.results) {
						const rIcon = r.exitCode === 0 ? theme.fg("success", "✓") : theme.fg("error", "✗");
						const displayItems = getDisplayItems(r.messages);

						container.addChild(new Spacer(1));
						container.addChild(
							new Text(

content.text:
								`${theme.fg("muted", `─── Step ${r.step}: `) + theme.fg("accent", r.agent)} ${rIcon}`,
								0,
								0,
							),
						);
						container.addChild(new Text(theme.fg("muted", "Task: ") + theme.fg("dim", r.task), 0, 0));

						// Show intermediate text and tool calls in order
						for (const item of displayItems) {
							if (item.type === "text") {
								if (item.text.trim()) {
									container.addChild(new Spacer(1));
									container.addChild(new Markdown(item.text.trim(), 0, 0, mdTheme));
								}
							} else {
								container.addChild(
									new Text(
										theme.fg("muted", "→ ") + formatToolCall(item.name, item.args, theme.fg.bind(theme)),
										0,
										0,
									),
								);
							}
						}

						const stepUsage = formatUsageStats(r.usage, r.model);
						if (stepUsage) container.addChild(new Text(theme.fg("dim", stepUsage), 0, 0));
					}

					const usageStr = formatUsageStats(aggregateUsage(details.results));
					if (usageStr) {
						container.addChild(new Spacer(1));
						container.addChild(new Text(theme.fg("dim", `Total: ${usageStr}`), 0, 0));
					}
					return container;
				}

				// Collapsed view
				let text =
					icon +
					" " +
					theme.fg("toolTitle", theme.bold("chain ")) +
					theme.fg("accent", `${successCount}/${details.results.length} steps`);
				for (const r of details.results) {
					const rIcon = r.exitCode === 0 ? theme.fg("success", "✓") : theme.fg("error", "✗");
					const displayItems = getDisplayItems(r.messages);
					text += `\n\n${theme.fg("muted", `─── Step ${r.step}: `)}${theme.fg("accent", r.agent)} ${rIcon}`;
					if (displayItems.length === 0) text += `\n${theme.fg("muted", "(no output)")}`;
					else text += `\n${renderDisplayItems(displayItems, 5)}`;
				}
				const usageStr = formatUsageStats(aggregateUsage(details.results));
				if (usageStr) text += `\n\n${theme.fg("dim", `Total: ${usageStr}`)}`;
				text += `\n${theme.fg("muted", "(Ctrl+O to expand)")}`;
				return new Text(text, 0, 0);
			}

			if (details.mode === "parallel") {
				const running = details.results.filter((r) => r.exitCode === -1).length;
				const successCount = details.results.filter((r) => r.exitCode !== -1 && !isFailedResult(r)).length;
				const failCount = details.results.filter((r) => r.exitCode !== -1 && isFailedResult(r)).length;
				const isRunning = running > 0;
				const icon = isRunning
					? theme.fg("warning", "⏳")
					: failCount > 0
						? theme.fg("warning", "◐")
						: theme.fg("success", "✓");
				const status = isRunning
					? `${successCount + failCount}/${details.results.length} done, ${running} running`
					: `${successCount}/${details.results.length} tasks`;

				if (expanded && !isRunning) {
					const container = new Container();
					container.addChild(
						new Text(
							`${icon} ${theme.fg("toolTitle", theme.bold("parallel "))}${theme.fg("accent", status)}`,
							0,
							0,
						),
					);

					for (const r of details.results) {
						const rIcon = isFailedResult(r) ? theme.fg("error", "✗") : theme.fg("success", "✓");
						const displayItems = getDisplayItems(r.messages);

						container.addChild(new Spacer(1));
						container.addChild(
							new Text(`${theme.fg("muted", "─── ") + theme.fg("accent", r.agent)} ${rIcon}`, 0, 0),
						);
						container.addChild(new Text(theme.fg("muted", "Task: ") + theme.fg("dim", r.task), 0, 0));

						// Show intermediate text and tool calls in order
						for (const item of displayItems) {
							if (item.type === "text") {
								if (item.text.trim()) {
									container.addChild(new Spacer(1));
									container.addChild(new Markdown(item.text.trim(), 0, 0, mdTheme));
								}
							} else {
								container.addChild(
									new Text(
										theme.fg("muted", "→ ") + formatToolCall(item.name, item.args, theme.fg.bind(theme)),
										0,
										0,
									),
								);
							}
						}

						const taskUsage = formatUsageStats(r.usage, r.model);
						if (taskUsage) container.addChild(new Text(theme.fg("dim", taskUsage), 0, 0));
					}

					const usageStr = formatUsageStats(aggregateUsage(details.results));
					if (usageStr) {
						container.addChild(new Spacer(1));
						container.addChild(new Text(theme.fg("dim", `Total: ${usageStr}`), 0, 0));
					}
					return container;
				}

				// Collapsed view (or still running)
				let text = `${icon} ${theme.fg("toolTitle", theme.bold("parallel "))}${theme.fg("accent", status)}`;
				for (const r of details.results) {
					const rIcon =
						r.exitCode === -1
							? theme.fg("warning", "⏳")
							: isFailedResult(r)
								? theme.fg("error", "✗")
								: theme.fg("success", "✓");
					const displayItems = getDisplayItems(r.messages);
					text += `\n\n${theme.fg("muted", "─── ")}${theme.fg("accent", r.agent)} ${rIcon}`;
					if (displayItems.length === 0)
						text += `\n${theme.fg("muted", r.exitCode === -1 ? "(running...)" : "(no output)")}`;
					else text += `\n${renderDisplayItems(displayItems, 5)}`;
				}
				if (!isRunning) {
					const usageStr = formatUsageStats(aggregateUsage(details.results));
					if (usageStr) text += `\n\n${theme.fg("dim", `Total: ${usageStr}`)}`;
				}
				if (!expanded) text += `\n${theme.fg("muted", "(Ctrl+O to expand)")}`;
				return new Text(text, 0, 0);
			}

			const text = result.content[0];
			return new Text(text?.type === "text" ? text.text : "(no output)", 0, 0);
		},
	});
}

/* -------------------------------------------------------------------------- */
/*                          Arbitration handler bodies                         */
/* -------------------------------------------------------------------------- */

/**
 * `inspect` — return more tail lines for a frozen process.
 *
 * Pure read; we do not touch the process. If the suspension is gone
 * (already resumed / killed / never existed), we return an error text
 * so the LLM can adjust.
 */
function handleInspect(
	inspectParams: { id: string; lines?: number },
	ctx: { cwd: string },
	makeDetails: (mode: "single" | "parallel" | "chain", suspensions?: SuspendedSnapshot["suspensions"]) => (results: SingleResult[]) => SubagentDetails | SuspendedSnapshot,
): AgentToolResult<SubagentDetails | SuspendedSnapshot> {
	const lines = inspectParams.lines ?? DEFAULT_INSPECT_LINES;
	const susp = getSuspension(inspectParams.id);
	if (!susp) {
		return {
			content: [
				{
					type: "text",
					text: `No active suspension with id "${inspectParams.id}". It may have been resumed, killed, or never existed.`,
				},
			],
			details: makeDetails("single")([]),
		};
	}
	const tail = summarizeTail(susp.messages, susp.stderr, lines);
	// Compute `inFlight` LIVE rather than trusting the frozen
	// snapshot. While suspended the recorded `susp.inFlight` could
	// be stale if a second freeze ever lands (e.g. resume → freeze
	// → user calls `inspect` instead of resume/kill); re-walking
	// `susp.messages` for an unmatched `toolCall` always gives the
	// currently-pending call. (Also defensively correct on the
	// first freeze.)
	const inFlightLive = extractInFlight(susp.messages);
	const idleMs = Date.now() - susp.lastEventAtMs;
	const text = JSON.stringify(
		{
			status: "idle_inspect",
			suspensionId: susp.id,
			idleMs,
			runningCommand: inFlightLive?.command ?? null,
			requestedTimeout: inFlightLive?.timeout ?? null,
			tail,
		},
		null,
		2,
	);
	return {
		content: [{ type: "text", text }],
		details: makeDetails("single")([liteToSingle(susp.partialResult)]),
	};
}

/**
 * `kill` — thaw then SIGKILL the process group, finalize the
 * suspension, return the partial transcript.
 *
 * Symmetric to handleResume. After kill we never re-attach the abort
 * handler (the process is dead), and the suspension is unregistered
 * synchronously.
 */
function handleKill(
	id: string,
	ctx: { cwd: string },
	makeDetails: (mode: "single" | "parallel" | "chain", suspensions?: SuspendedSnapshot["suspensions"]) => (results: SingleResult[]) => SubagentDetails | SuspendedSnapshot,
): AgentToolResult<SubagentDetails | SuspendedSnapshot> {
	const susp = getSuspension(id);
	if (!susp) {
		return {
			content: [
				{
					type: "text",
					text: `No active suspension with id "${id}". It may have been resumed, killed, or never existed.`,
				},
			],
			details: makeDetails("single")([]),
		};
	}

	// Mark the suspension as cancelled BEFORE we touch the process
	// group. `handleResume`'s close/error handlers consult this flag:
	// when set, they do NOT advance the parent chain/parallel state
	// (otherwise a kill followed by SIGKILL-then-close would still
	// spawn orphan chain remaining steps, which was the R1 hang).
	susp.cancelled = true;

	// Thaw before kill. SIGKILL to a stopped process works at the
	// kernel level, but thawing first lets any pending cleanup (file
	// handles, child waits) unwind.
	thawProcessGroup(susp.proc);

	// Deliberately do NOT re-attach the user's AbortSignal: the
	// process is about to die and a late-arriving Ctrl+C after the
	// kill returns would only confuse the LLM with a second error.

	// Synchronous SIGKILL. `process.kill(-pid, "SIGKILL")` returns
	// immediately and the kernel delivers the signal right away
	// (SIGKILL is not queued like SIGTERM). Doing it inline avoids
	// the fire-and-forget race where the proc exited cleanly before
	// the 100ms timer and the timer then fired against a re-used
	// pid. The 100ms timer is kept as a fallback for the rare case
	// the synchronous call is denied (EPERM after thaw) — it will
	// at worst escalate on a defunct pid.
	killProcessGroup(susp.proc);
	setTimeout(() => killProcessGroup(susp.proc), 100);

	// Mark the partial result as aborted so isFailedResult returns true
	// and the LLM sees it as a hard failure.
	const partial: SingleResult = {
		...susp.partialResult,
		exitCode: -1,
		stopReason: "aborted",
	};

	// Unregister immediately so subsequent resume / inspect on this id
	// correctly errors out.
	unregisterSuspension(susp.id);
	return {
		content: [
			{
				type: "text",
				text: `Killed suspended sub-agent ${susp.partialResult.agent}. Partial transcript follows:\n\n${getFinalOutput(partial.messages) || "(no output)"}`,
			},
		],
		details: makeDetails("single")([partial]),
	};
}

/**
 * `resume` — thaw the process group, re-arm the watchdog, and wait
 * for the process to exit. On exit we resume the *parent* (chain /
 * parallel) computation as if the freeze hadn't happened.
 *
 * The watch-and-wait loop is a local `new Promise` that resolves with
 * a fresh `SingleRunOutcome`. Once we have it we splice the result
 * into the surrounding chain / parallel state and continue / finalize.
 */
/** Map a `Job` discriminator onto the `makeDetails` mode key. Used
 *  by `handleResume` to build the correct suspended-render details
 *  regardless of whether we re-froze on the first or the second leg. */
function resumeMode(job: Job): "single" | "chain" | "parallel" {
	return job.kind;
}

function handleResume(
	id: string,
	signal: AbortSignal | undefined,
	onUpdate: OnUpdateCallback | undefined,
	ctx: { cwd: string },
	agents: AgentConfig[],
	allToolNames: string[],
	agentScope: AgentScope,
	discovery: { projectAgentsDir: string | null },
	makeDetails: (mode: "single" | "parallel" | "chain", suspensions?: SuspendedSnapshot["suspensions"]) => (results: SingleResult[]) => SubagentDetails | SuspendedSnapshot,
	modelOverride: string | undefined,
): Promise<AgentToolResult<SubagentDetails | SuspendedSnapshot>> {
	const susp = getSuspension(id);
	if (!susp) {
		return Promise.resolve({
			content: [
				{
					type: "text",
					text: `No active suspension with id "${id}". It may have been resumed, killed, or never existed.`,
				},
			],
			details: makeDetails("single")([]),
		});
	}

	// Thaw. After this the child resumes whatever it was doing.
	const thawed = thawProcessGroup(susp.proc);
	if (!thawed && isPosixSuspendSupported()) {
		// Thaw failed on POSIX. The child is stuck; treat it as a
		// failed exit so the LLM doesn't keep polling forever.
		const partial: SingleResult = {
			...susp.partialResult,
			exitCode: -1,
			stopReason: "aborted",
		};
		unregisterSuspension(susp.id);
		return Promise.resolve({
			content: [
				{
					type: "text",
					text: `Failed to thaw suspended sub-agent ${susp.partialResult.agent} (SIGCONT error).`,
				},
			],
			details: makeDetails("single")([partial]),
		});
	}

	// Wire up an "I just resumed" listener so the next time the
	// process closes (or errors) we finalize the parent computation.
	const proc = susp.proc;
	const idleTimeoutMs = resolveIdleTimeoutMs();

	return new Promise<AgentToolResult<SubagentDetails | SuspendedSnapshot>>((resolve) => {
		let buffer = "";
		// Build on top of the already-accumulated messages / stderr.
		const partialLite = susp.partialResult;
		const partial: SingleResult = liteToSingle(partialLite);
		partial.exitCode = 0; // reset for the resumed leg

		let lastEventAtMs = Date.now();
		// `resumedSuspended` tracks whether THIS resume leg has itself
		// frozen the process. Mirrors the same flag in
		// `runSingleAgent` so re-armed listeners can short-circuit
		// (otherwise the original `proc.on('data')` handler would
		// re-arm the watchdog and create a duplicate suspension).
		let resumedSuspended = false;
		// The currently registered abort handler for this leg. NULL
		// when none is active (initial state and after a re-freeze
		// before the next abort arrives). We need this exact
		// reference so the second-freeze path can detach the
		// listener it registered via `reAttachAbortListener` —
		// detachAbortListener(signal, null) is a no-op.
		let activeAbortHandler: (() => void) | null = null;

		let idleTimer: NodeJS.Timeout | null = null;
		const armWatchdog = () => {
			if (resumedSuspended) return;
			if (idleTimer) clearTimeout(idleTimer);
			idleTimer = setTimeout(() => {
				idleTimer = null;
				// Race guard (see runSingleAgent / armWatchdog for the
				// full story). If `close` already won, exit cleanly.
				if (proc.exitCode !== null) {
					disarmWatchdog();
					return;
				}
				// Frozen again. Resolve as a second suspension and
				// let the caller (LLM) decide whether to resume or
				// kill. The close handler of THIS leg is detached
				// below so the SIGKILL that a `kill` will eventually
				// issue cannot reach back into this promise and
				// spawn chain remaining steps (the R1 hang).
				const frozen = freezeProcessGroup(proc);
				if (!frozen) {
					partial.exitCode = -1;
					partial.stopReason = "aborted";
					killProcessGroup(proc);
					// Mark finalized so the close handler that the
					// SIGKILL triggers can't spawn orphan chain
					// steps (R1).
					finalized = true;
					unregisterSuspension(susp.id);
					resolve({
						content: [
							{
								type: "text",
								text: `Resumed sub-agent re-froze then was force-killed (no SIGSTOP on win32). Partial transcript follows:\n\n${getFinalOutput(partial.messages) || "(no output)"}`,
							},
						],
						details: makeDetails(resumeMode(susp.job))([partial]),
					});
					return;
				}
				const newId = newSuspensionId();
				const inFlight = extractInFlight(partial.messages);
				const suspension2: Suspension = {
					id: newId,
					proc,
					inFlight,
					messages: partial.messages,
					stderr: partial.stderr,
					invocation: susp.invocation,
					// Carry over the FULL surrounding-job state so the
					// next `resume` call knows whether we are mid-
					// single, chain, or parallel — and so chain /
					// parallel resume can keep walking the same step
					// list (parallel now carries the full `tasks`).
					job: susp.job,
					partialResult: singleToLite(partial),
					lastEventAtMs,
					originalSignal: susp.originalSignal,
					// The current active handler is the one we
					// registered below; will be cleared below once
					// we detach, so the registered suspension's
					// `activeAbortHandler` reflects the actual state
					// (no handler currently attached).
					activeAbortHandler,
					cancelled: false,
				};
				detachAbortListener(susp.originalSignal, activeAbortHandler);
				suspension2.activeAbortHandler = null;
				activeAbortHandler = null;
				resumedSuspended = true;
				// Mark this leg as finalized BEFORE we resolve so a
				// late `close` event (e.g. from a subsequent kill
				// SIGKILL) cannot call `finalizeAndContinue` and
				// spawn orphan chain steps (R1). The double-resolve
				// itself is a no-op on the promise, but the resolve
				// ARGUMENT is evaluated eagerly.
				finalized = true;
				registerSuspension(suspension2);
				unregisterSuspension(susp.id);
				resolve({
					content: [
						{
							type: "text",
							text: JSON.stringify(
								{
									status: "idle_suspended",
									suspensionId: newId,
									idleMs: Date.now() - lastEventAtMs,
									runningCommand: inFlight?.command ?? null,
									requestedTimeout: inFlight?.timeout ?? null,
									tail: summarizeTail(partial.messages, partial.stderr, DEFAULT_TAIL_LINES),
								},
								null,
								2,
							),
						},
					],
					// Use the ORIGINAL mode (chain/parallel), not
					// "single" — the renderer uses `details.mode` to
					// pick the right display path. A chain job that
					// re-froze must still render as a chain
					// suspension so the LLM knows it has a multi-
					// step result to resume, not a single-agent
					// transcript.
					details: makeDetails(resumeMode(susp.job))([partial]),
				});
			}, idleTimeoutMs);
		};
		const disarmWatchdog = () => {
			if (idleTimer) {
				clearTimeout(idleTimer);
				idleTimer = null;
			}
		};

		const processLine = (line: string) => {
			if (!line.trim()) return;
			let event: any;
			try {
				event = JSON.parse(line);
			} catch {
				return;
			}
			if (event.type === "message_end" && event.message) {
				const msg = event.message as Message;
				partial.messages.push(msg);
				if (msg.role === "assistant") {
					partial.usage.turns++;
					const usage = msg.usage;
					if (usage) {
						partial.usage.input += usage.input || 0;
						partial.usage.output += usage.output || 0;
						partial.usage.cacheRead += usage.cacheRead || 0;
						partial.usage.cacheWrite += usage.cacheWrite || 0;
						partial.usage.cost += usage.cost?.total || 0;
						partial.usage.contextTokens = usage.totalTokens || 0;
					}
					if (!partial.model && msg.model) partial.model = msg.model;
					if (msg.stopReason) partial.stopReason = msg.stopReason;
					if (msg.errorMessage) partial.errorMessage = msg.errorMessage;
				}
				if (onUpdate) {
					onUpdate({
						content: [{ type: "text", text: getFinalOutput(partial.messages) || "(running...)" }],
						details: makeDetails("single")([partial]),
					});
				}
			}
			if (event.type === "tool_result_end" && event.message) {
				partial.messages.push(event.message as Message);
				if (onUpdate) {
					onUpdate({
						content: [{ type: "text", text: getFinalOutput(partial.messages) || "(running...)" }],
						details: makeDetails("single")([partial]),
					});
				}
			}
		};

		// Wire stdout/stderr again. They were already wired before the
		// freeze, but Node event listeners are kept across SIGSTOP, so
		// the listeners are intact. We just need to re-arm the
		// watchdog timer.
		const onStdoutData = (data: Buffer) => {
			lastEventAtMs = Date.now();
			armWatchdog();
			buffer += data.toString();
			const lines = buffer.split("\n");
			buffer = lines.pop() || "";
			for (const line of lines) processLine(line);
		};
		const onStderrData = (data: Buffer) => {
			lastEventAtMs = Date.now();
			armWatchdog();
			partial.stderr += data.toString();
		};

		proc.stdout?.on("data", onStdoutData);
		proc.stderr?.on("data", onStderrData);

		// `finalized` flips to true the moment we resolve the
		// outer promise. After that the close / error handlers
		// are inert — even if the proc fires a final `close`
		// (e.g. because handleKill just SIGKILL'd it after we
		// resolved from a re-freeze), we MUST NOT spawn a second
		// set of chain / parallel remaining steps. That was the
		// R1 hang: the close handler would call `resolve(...)`
		// again (no-op for the promise itself) but the ARGUMENT
		// to resolve is evaluated eagerly, which calls
		// `runChainRemaining` and spawns orphan chain steps.
		let finalized = false;

		const finalizeAndContinue = (result: SingleResult, job: Job) => {
			// Re-entrancy guard. If we already resolved (e.g. via
			// the watchdog timer that fired a second freeze), the
			// close handler firing for a SIGKILL'd proc must not
			// spawn anything. `resolve()` is a no-op on the second
			// call, but its argument is evaluated eagerly — that
			// was the R1 orphan-chain-step bug.
			if (finalized) return;
			finalized = true;
			disarmWatchdog();
			unregisterSuspension(susp.id);

			// If the proc was killed by handleKill, we still want
			// to resolve cleanly with the partial transcript (the
			// caller already got its kill-text response from
			// handleKill). Reaching here from the close handler
			// after a kill means the kill-path response is
			// already returned; the late resolve is harmless but
			// we DO want to skip the chain/parallel continuation
			// to avoid orphan steps. The `susp.cancelled` flag
			// handles that.
			if (susp.cancelled) {
				resolve({
					content: [
						{
							type: "text",
							text: getFinalOutput(result.messages) || "(no output)",
						},
					],
					details: makeDetails(resumeMode(job))([result]),
				});
				return;
			}

			if (job.kind === "single") {
				const isError = isFailedResult(result);
				const out = getFinalOutput(result.messages) || "(no output)";
				resolve({
					content: isError
						? [{ type: "text", text: `Agent ${result.stopReason || "failed"}: ${out}` }]
						: [{ type: "text", text: out }],
					details: makeDetails("single")([result]),
					isError,
				});
				return;
			}
			if (job.kind === "chain") {
				// Continue the chain from `job.index` using the partial
				// result we just resumed as step `job.index`.
				const allResults: SingleResult[] = [...job.results.map(liteToSingle), result];
				const previousOutput = getFinalOutput(result.messages);
				resolve(
					runChainRemaining(
						job.steps.slice(job.index + 1),
						job.index + 1,
						previousOutput,
						allResults,
						job.steps,
						ctx,
						signal,
						onUpdate,
						agents,
						allToolNames,
						agentScope,
						discovery,
						makeDetails,
						modelOverride,
					),
				);
				return;
			}
			if (job.kind === "parallel") {
				// Rebuild a fully-ordered result array of length
				// `tasks.length` from the original task spec — NOT
				// from `completedResults` (which excludes the
				// suspended index and so is one slot short). For
				// every completed sibling we lift the lite back to
				// a `SingleResult`; the resumed `result` is dropped
				// into its original index verbatim.
				const merged: SingleResult[] = new Array(job.tasks.length);
				let sibCursor = 0;
				for (let i = 0; i < job.tasks.length; i++) {
					if (i === job.index) {
						merged[i] = result;
					} else {
						merged[i] = liteToSingle(job.completedResults[sibCursor]!);
						sibCursor++;
					}
				}
				const successCount = merged.filter((r) => !isFailedResult(r)).length;
				const summaries = merged.map((r) => {
					const output = truncateParallelOutput(getResultOutput(r));
					const status = isFailedResult(r)
						? `failed${r.stopReason && r.stopReason !== "end" ? ` (${r.stopReason})` : ""}`
						: "completed";
					return `### [${r.agent}] ${status}\n\n${output}`;
				});
				resolve({
					content: [
						{
							type: "text",
							text: `Parallel: ${successCount}/${merged.length} succeeded\n\n${summaries.join("\n\n---\n\n")}`,
						},
					],
					details: makeDetails("parallel")(merged),
				});
				return;
			}
		};

		proc.once("close", (code) => {
			// Re-entrancy guard: if a previous path already
			// resolved (e.g. the watchdog fired a re-freeze and
			// the LLM's subsequent kill SIGKILL'd the proc), do
			// NOT advance chain/parallel state — that would
			// spawn orphan steps. `finalized` is set inside
			// `finalizeAndContinue`; check it here so a stale
			// close event after a kill is ignored.
			if (finalized) return;
			if (resumedSuspended) return;
			if (buffer.trim()) processLine(buffer);
			const result: SingleResult = { ...partial, exitCode: code ?? 0 };
			finalizeAndContinue(result, susp.job);
		});

		proc.once("error", () => {
			if (finalized) return;
			if (resumedSuspended) return;
			const result: SingleResult = { ...partial, exitCode: 1 };
			finalizeAndContinue(result, susp.job);
		});

		// Re-attach the user's AbortSignal so Ctrl+C works on the
		// resumed leg. The helper returns the same function reference
		// we need to detach on a subsequent freeze, so we MUST keep
		// it in `activeAbortHandler` rather than discard it (the
		// previous code did, which leaked the listener into the
		// user's signal for the rest of the lifetime and meant a
		// SIGTERM on the second-leg Ctrl+C ended up racing the
		// next resume's kill decision).
		activeAbortHandler = reAttachAbortListener(signal, proc, {
			isSuspended: () => resumedSuspended,
		});

		// Arm the watchdog immediately.
		armWatchdog();
	});
}

