async function runChainRemaining(
	remaining: Array<{ agent: string; task: string; cwd?: string; model?: string }>,
	startIndex: number,
	previousOutput: string,
	allResults: SingleResult[],
	fullChain: Array<{ agent: string; task: string; cwd?: string; model?: string }>,
	ctx: { cwd: string },
	signal: AbortSignal | undefined,
	onUpdate: OnUpdateCallback | undefined,
	agents: AgentConfig[],
	allToolNames: string[],
	agentScope: AgentScope,
	discovery: { projectAgentsDir: string | null },
	makeDetails: (mode: "single" | "parallel" | "chain", suspensions?: SuspendedSnapshot["suspensions"]) => (results: SingleResult[]) => SubagentDetails | SuspendedSnapshot,
	modelOverride: string | undefined,
): Promise<AgentToolResult<SubagentDetails | SuspendedSnapshot>> {
	let prev = previousOutput;
	for (let i = 0; i < remaining.length; i++) {
		const idx = startIndex + i;
		const r = await runChainStep(
			idx,
			remaining[i]!,
			fullChain,
			allResults,
			prev,
			ctx,
			signal,
			onUpdate,
			agents,
			allToolNames,
			agentScope,
			discovery,
			makeDetails,
			modelOverride,
		);
		if ("early" in r) return r.early;
		allResults[idx] = r.result;
		if (r.isError) {
			const errorMsg = getResultOutput(r.result);
			return {
				content: [{ type: "text", text: `Chain stopped at step ${idx + 1} (${remaining[i]!.agent}): ${errorMsg}` }],
				details: makeDetails("chain")(allResults),
				isError: true,
			};
		}
		prev = getFinalOutput(r.result.messages);
	}
	return {
		content: [{ type: "text", text: getFinalOutput(allResults[allResults.length - 1]!.messages) || "(no output)" }],
		details: makeDetails("chain")(allResults),
	};
}

type ChainStepOutcome =
	| { result: SingleResult; isError: boolean }
	| { early: AgentToolResult<SubagentDetails | SuspendedSnapshot> };

async function runChainStep(
	stepIndex: number,
	step: { agent: string; task: string; cwd?: string; model?: string },
	fullChain: Array<{ agent: string; task: string; cwd?: string; model?: string }>,
	results: SingleResult[],
	previousOutput: string,
	ctx: { cwd: string },
	signal: AbortSignal | undefined,
	onUpdate: OnUpdateCallback | undefined,
	agents: AgentConfig[],
	allToolNames: string[],
	agentScope: AgentScope,
	discovery: { projectAgentsDir: string | null },
	makeDetails: (mode: "single" | "parallel" | "chain", suspensions?: SuspendedSnapshot["suspensions"]) => (results: SingleResult[]) => SubagentDetails | SuspendedSnapshot,
	modelOverride: string | undefined,
): Promise<ChainStepOutcome> {
	const taskWithContext = step.task.replace(/\{previous\}/g, previousOutput);
	const chainUpdate: OnUpdateCallback | undefined = onUpdate
		? (partial) => {
				const currentResult = partial.details?.results?.[0] as SingleResult | undefined;
				if (currentResult) {
					const merged = [...results, currentResult];
					onUpdate({
						content: partial.content,
						details: makeDetails("chain")(merged),
					});
				}
			}
		: undefined;

	const outcome = await runSingleAgent(
		ctx.cwd,
		agents,
		step.agent,
		taskWithContext,
		step.cwd,
		stepIndex + 1,
		signal,
		chainUpdate,
		makeDetails("chain"),
		allToolNames,
		step.model ?? modelOverride,
		{
			kind: "chain",
			steps: fullChain,
			index: stepIndex,
			previousOutput,
			results: results.map(singleToLite),
		},
		stepIndex + 1,
	);
	if (outcome.kind === "suspended") {
		const built = buildSuspendedSnapshot("chain", [
			{ suspensionId: outcome.id, snapshot: outcome.snapshot, lastEventAtMs: outcome.lastEventAtMs },
		]);
		return {
			early: {
				content: [
					{
						type: "text",
						text: JSON.stringify(
							{
								status: "idle_suspended",
								suspensionId: outcome.id,
								idleMs: Date.now() - outcome.lastEventAtMs,
								runningCommand: built[0]?.runningCommand ?? null,
								requestedTimeout: built[0]?.requestedTimeout ?? null,
								tail: built[0]?.tail ?? [],
							},
							null,
							2,
						),
					},
				],
				details: makeDetails("chain", built)([...results, outcome.snapshot]),
			},
		};
	}
	const result = outcome.result;
	return { result, isError: isFailedResult(result) };
}

async function runParallel(
	tasks: Array<{ agent: string; task: string; cwd?: string; model?: string }>,
	ctx: { cwd: string },
	signal: AbortSignal | undefined,
	onUpdate: OnUpdateCallback | undefined,
	agents: AgentConfig[],
	allToolNames: string[],
	agentScope: AgentScope,
	discovery: { projectAgentsDir: string | null },
	makeDetails: (mode: "single" | "parallel" | "chain", suspensions?: SuspendedSnapshot["suspensions"]) => (results: SingleResult[]) => SubagentDetails | SuspendedSnapshot,
	modelOverride: string | undefined,
): Promise<AgentToolResult<SubagentDetails | SuspendedSnapshot>> {
	if (tasks.length > MAX_PARALLEL_TASKS) {
		return {
			content: [
				{
					type: "text",
					text: `Too many parallel tasks (${tasks.length}). Max is ${MAX_PARALLEL_TASKS}.`,
				},
			],
			details: makeDetails("parallel")([]),
		};
	}

	const allResults: SingleResult[] = new Array(tasks.length);
	for (let i = 0; i < tasks.length; i++) {
		allResults[i] = {
			agent: tasks[i]!.agent,
			agentSource: "unknown",
			task: tasks[i]!.task,
			exitCode: -1,
			messages: [],
			stderr: "",
			usage: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, cost: 0, contextTokens: 0, turns: 0 },
		};
	}

	const emitParallelUpdate = (suspensions?: SuspendedSnapshot["suspensions"]) => {
		if (onUpdate) {
			const running = allResults.filter((r) => r.exitCode === -1).length;
			const done = allResults.filter((r) => r.exitCode !== -1).length;
			onUpdate({
				content: [
					{ type: "text", text: `Parallel: ${done}/${allResults.length} done, ${running} running...` },
				],
				details: makeDetails("parallel", suspensions)([...allResults]),
			});
		}
	};

	const tasks_ = await mapWithConcurrencyLimit(tasks, MAX_CONCURRENCY, async (t, index) => {
		const r = await runSingleAgent(
			ctx.cwd,
			agents,
			t.agent,
			t.task,
			t.cwd,
			undefined,
			signal,
			(partial) => {
				const r0 = partial.details?.results?.[0] as SingleResult | undefined;
				if (r0) {
					allResults[index] = r0;
					emitParallelUpdate();
				}
			},
			makeDetails("parallel"),
			allToolNames,
			t.model ?? modelOverride,
			{
				kind: "parallel",
				// Carry the FULL task list so the resume path can
				// rebuild a length-N result array (see
				// `finalizeAndContinue`'s parallel branch). Without
				// this, multi-task suspensions would lose siblings
				// or write past the end of the merged array.
				tasks,
				index,
				taskSpec: t,
				completedResults: allResults
					.filter((_, i) => i !== index && allResults[i]!.exitCode !== -1)
					.map(singleToLite),
			},
			0,
		);
		if (r.kind === "suspended") {
			// We can't both `await mapWithConcurrencyLimit` and stitch
			// suspensions, so we let the suspended placeholder sit at
			// this index and let the post-loop pass collect it.
			allResults[index] = r.snapshot;
			return { suspended: true, id: r.id, lastEventAtMs: r.lastEventAtMs, snapshot: r.snapshot } as const;
		}
		allResults[index] = r.result;
		emitParallelUpdate();
		return { suspended: false as const, result: r.result };
	});

	// Collect suspensions from the task results. We also patch each
// suspension's `job.completedResults` with the *final* allResults
// state — the per-task `runSingleAgent` only saw an empty
// `completedResults` snapshot because nothing had finished when it
// was called, and we need the resume path to know about sibling
// tasks that completed while this one was frozen.
	const suspensions: SuspendedSnapshot["suspensions"] = [];
	let anySuspended = false;
	for (let i = 0; i < tasks_.length; i++) {
		const t = tasks_[i]!;
		if ("suspended" in t && t.suspended) {
			anySuspended = true;
			const liveSusp = getSuspension(t.id);
			if (liveSusp && liveSusp.job.kind === "parallel") {
				liveSusp.job = {
					...liveSusp.job,
					completedResults: allResults
						.filter((_, j) => j !== liveSusp.job.index)
						.map(singleToLite),
				};
			}
			const built = buildSuspendedSnapshot("parallel", [
				{ suspensionId: t.id, snapshot: t.snapshot, lastEventAtMs: t.lastEventAtMs },
			]);
			suspensions.push(built[0]!);
		}
	}

	if (anySuspended) {
		const completedResults = tasks_
			.map((t, i) => ({ t, i }))
			.filter((x) => "result" in x.t)
			.map((x) => getResultOutput((x.t as { result: SingleResult }).result));
		const suspendedText = suspensions
			.map(
				(s) =>
					`- suspensionId: ${s.suspensionId} (idleMs=${s.idleMs}, command=${s.runningCommand ?? "(none)"})`,
			)
			.join("\n");
		return {
			content: [
				{
					type: "text",
					text: JSON.stringify(
						{
							status: "idle_suspended",
							suspensions: suspensions.map((s) => ({
								suspensionId: s.suspensionId,
								idleMs: s.idleMs,
								runningCommand: s.runningCommand,
								requestedTimeout: s.requestedTimeout,
								tail: s.tail,
							})),
							completedCount: completedResults.length,
							totalTasks: tasks.length,
						},
						null,
						2,
					) + `\n\n${suspendedText}`,
				},
			],
			details: makeDetails("parallel", suspensions)([...allResults]),
		};
	}

	const successCount = allResults.filter((r) => !isFailedResult(r)).length;
	const summaries = allResults.map((r) => {
		const output = truncateParallelOutput(getResultOutput(r));
		const status = isFailedResult(r)
			? `failed${r.stopReason && r.stopReason !== "end" ? ` (${r.stopReason})` : ""}`
			: "completed";
		return `### [${r.agent}] ${status}\n\n${output}`;
	});
	return {
		content: [
			{
				type: "text",
				text: `Parallel: ${successCount}/${allResults.length} succeeded\n\n${summaries.join("\n\n---\n\n")}`,
			},
		],
		details: makeDetails("parallel")(allResults),
	};
}

/* -------------------------------------------------------------------------- */
/*                       Parent-process cleanup (Stage G)                     */
/* -------------------------------------------------------------------------- */

/**
 * Best-effort cleanup of any process group we left frozen.
 *
 * Hooks:
 *   - `process.on("exit")` — synchronous; we SIGCONT then SIGKILL each
 *     suspended process group. `kill` is synchronous so this fits in
 *     the `exit` handler.
 *   - SIGINT / SIGTERM — best-effort, then re-raise the default action.
 *
 * Known gap: SIGKILL to *ourselves* (`kill -9`) does not let Node run
 * any handlers, including this `exit` hook. There is no userland
 * solution for that. Comment is intentional.
 */
// Module-level flag. The extension's default export pulls
// `parentProcessCleanup` indirectly at module load, and tests may
// `import` the module multiple times in the same process — without
// idempotency each import would stack another `process.on("exit")`
// handler. Re-arming is harmless but it bloats signal listener
// counts and makes leak diagnostics noisy. Use a guard symbol so we
// register at most once.
let __parentProcessCleanupRegistered = false;
function parentProcessCleanup(): void {
	if (__parentProcessCleanupRegistered) return;
	__parentProcessCleanupRegistered = true;
	const reap = () => {
		const suspended = getAllSuspensions();
		for (const s of suspended) {
			try {
				if (s.proc.pid) {
					// Thaw first so SIGKILL is delivered immediately.
					try {
						process.kill(-s.proc.pid, "SIGCONT");
					} catch {
						/* swallow */
					}
					process.kill(-s.proc.pid, "SIGKILL");
				}
			} catch {
				/* swallow */
			}
		}
	};

	process.on("exit", reap);

	const onSignal = (sig: NodeJS.Signals) => {
		reap();
		// Restore default behavior so the parent actually dies.
		process.removeListener(sig, onSignal);
		process.kill(process.pid, sig);
	};
	process.on("SIGINT", onSignal);
	process.on("SIGTERM", onSignal);
}

// Test-only escape hatch: clear the guard so a fresh registration
// can be applied (useful when the test wants to assert that the
// process listeners ARE registered, or has to import the module
// twice through dynamic import).
export function __resetParentProcessCleanupForTests(): void {
	__parentProcessCleanupRegistered = false;
}

parentProcessCleanup();

/**
 * suspensions — registry + process-group helpers for the idle-watchdog
 * arbitration protocol implemented by the subagent extension.
 *
 * Why this exists
 * ---------------
 * When a sub-`pi` process goes silent for too long (default 600s), the
 * parent can't simply SIGKILL it: that throws away the partial transcript
 * and breaks long-running parallel/chain jobs. Instead we SIGSTOP the
 * whole process group (frozen at the kernel level — child `pi`, its
 * bash subprocesses, the deadlock-grandchildren, all of them) and hand
 * control back to the parent LLM with a fact-only snapshot. The parent
 * then decides to `resume` / `kill` / `inspect` via a follow-up call to
 * the same subagent tool.
 *
 * This module owns the data structures and the OS-level process-group
 * plumbing. The orchestration (when to freeze, what to return, how to
 * re-enter `runSingleAgent` on resume) lives in `index.ts`.
 *
 * Module-level state
 * ------------------
 * The registry is a single `Map<SuspensionId, Suspension>` that lives
 * for the lifetime of the parent `pi` process. It is keyed by an
 * auto-incremented id; values hold a live `ChildProcess` plus the
 * resume state (`Job`) needed to continue a chain/parallel job after
 * the SIGCONT.
 *
 * Platform notes
 * --------------
 *   - POSIX: `process.kill(-pgid, signal)` operates on the whole
 *     process group. SIGSTOP freezes everyone; SIGCONT resumes; SIGKILL
 *     is unstoppable. SIGTERM is unreliable on a stopped process
 *     because the kernel doesn't deliver pending signals until the
 *     process is running again, so kill flows thaw first, then SIGKILL.
 *   - Windows: process groups don't exist in the POSIX sense. There is
 *     no SIGSTOP equivalent. We degrade gracefully:
 *       * `freezeProcessGroup` / `thawProcessGroup` are no-ops on win32
 *         (so `isPosixSuspendSupported()` returns `false`).
 *       * `killProcessGroup` shells out to `taskkill /pid <pid> /T /F`,
 *         which terminates the pid and its descendants synchronously.
 *         `/T` = tree, `/F` = force. Any failure is swallowed — best
 *         effort, like everything in this file.
 *
 *     Because we cannot SIGSTOP on win32, the idle watchdog there takes
 *     a different path: it directly `killProcessGroup`s the suspended
 *     sub-process instead of registering a Suspension. The comment in
 *     `index.ts` records this decision.
 */

import { spawnSync, type ChildProcess } from "node:child_process";
import { randomBytes } from "node:crypto";
import type { Message } from "@earendil-works/pi-ai";

/** What kind of subagent job the suspended run belongs to. */
export type JobKind = "single" | "chain" | "parallel";

/**
 * Snapshot of the tool call that was in flight when we froze.
 *
 * `command` / `timeout` are populated only for bash calls; other tools
 * (`read`, `grep`, …) still surface the tool name so the LLM knows
 * what was hanging. Used by the `idle_suspended` snapshot returned to
 * the parent so it can decide whether to resume / kill / inspect.
 */
export interface InFlightToolCall {
	toolName: string;
	command?: string;
	timeout?: number;
}

/**
 * Resume state for chain/parallel jobs.
 *
 *   - `kind: "single"` — no extra state, the run is fully self-contained.
 *   - `kind: "chain"` — `steps[i].task` is the original spec; we replay
 *     steps from `index` onward, threading `previousOutput` from the
 *     last completed step. `results` holds the *completed* steps so the
 *     resume can stitch them back in. `previousOutput` is the last
 *     step's final output, ready to substitute into `{previous}`.
 *   - `kind: "parallel"` — `tasks` is the full original task list
 *     (length N), so on resume we can rebuild a fully-ordered result
 *     array of length N. `completedResults` is the *other* indices
 *     that finished while this one was frozen (the suspended index
 *     itself is excluded). Multiple tasks may be suspended at the
 *     same time; each registers its own `Suspension` with its own
 *     `index`. Resuming one should not stomp on the others' slots.
 */
export type Job =
	| { kind: "single" }
	| {
			kind: "chain";
			steps: Array<{
				agent: string;
				task: string;
				cwd?: string;
				model?: string;
			}>;
			index: number;
			previousOutput: string;
			results: SingleResultLite[];
	  }
	| {
			kind: "parallel";
			tasks: Array<{ agent: string; task: string; cwd?: string; model?: string }>;
			index: number;
			taskSpec: { agent: string; task: string; cwd?: string; model?: string };
			completedResults: SingleResultLite[];
	  };

/**
 * Lightweight per-step result carried across a freeze boundary.
 *
 * The parent run builds a richer `SingleResult` for display, but for
 * the purposes of stitching chain/parallel state across a freeze we
 * only need the fields that get fed into the next step's prompt
 * (`getFinalOutput(messages)`) or assembled into the final summary.
 */
export interface SingleResultLite {
	agent: string;
	agentSource: "user" | "project" | "unknown";
	task: string;
	exitCode: number;
	messages: Message[];
	usage: {
		input: number;
		output: number;
		cacheRead: number;
		cacheWrite: number;
		cost: number;
		contextTokens: number;
		turns: number;
	};
	model?: string;
	stopReason?: string;
	errorMessage?: string;
	step?: number;
}

/**
 * A live suspended sub-process plus everything needed to resume / kill
 * / inspect it from a follow-up tool call.
 *
 * `lastEventAtMs` is the wall-clock time of the most recent stdout
 * NDJSON line OR stderr chunk. The idle watchdog updates it on every
 * line and every stderr data event; the snapshot returns
 * `Date.now() - lastEventAtMs` as `idleMs` so the parent can tell
 * whether the freeze was "just hit 600s" or "has been dead for hours".
 *
 * `activeAbortHandler` is *the* abort handler currently registered on
 * the caller's `originalSignal`. It is set at freeze time and updated
 * on resume / re-freeze so we can `detachAbortListener(..., h)` with
 * the exact function reference that was added (the previous design
 * stored a `null` placeholder and then `detachAbortListener(null)`,
 * which is a no-op and leaks the listener for the lifetime of the
 * signal). `activeAbortHandler` may be `null` if the run was started
 * without a signal or after a clean kill (which never re-attaches).
 */
export interface Suspension {
	id: string;
	proc: ChildProcess;
	inFlight: InFlightToolCall | null;
	messages: Message[];
	stderr: string;
	invocation: string;
	job: Job;
	partialResult: SingleResultLite;
	lastEventAtMs: number;
	originalSignal: AbortSignal | undefined;
	activeAbortHandler: (() => void) | null;
	/**
	 * Set by `handleKill` immediately before SIGKILL is delivered so
	 * `handleResume`'s close/error handlers can tell "natural exit"
	 * apart from "user killed me" and refuse to spawn orphan chain /
	 * parallel remaining steps. Default false.
	 */
	cancelled: boolean;
}

export type SuspensionId = string;

/* -------------------------------------------------------------------------- */
/*                              ID generation                                 */
/* -------------------------------------------------------------------------- */

let __suspensionCounter = 0;

/**
 * Mint a fresh suspension id.
 *
 * Format: `susp_<base36-counter>_<6-hex>` where the counter is
 * monotonically increasing within the process and the hex tail is a
 * random discriminator. Two suspensions minted in the same millisecond
 * still get distinct ids because of the random suffix.
 *
 * Exported so tests can pin the format without going through a real
 * freeze path.
 */
export function newSuspensionId(): SuspensionId {
	__suspensionCounter += 1;
	const tail = randomBytes(3).toString("hex");
	return `susp_${__suspensionCounter.toString(36)}_${tail}`;
}

/* -------------------------------------------------------------------------- */
/*                              Registry                                      */
/* -------------------------------------------------------------------------- */

const registry = new Map<SuspensionId, Suspension>();

/** Register a suspension. Overwrites any prior entry with the same id
 *  (shouldn't happen in practice — ids are unique). */
export function registerSuspension(s: Suspension): void {
	registry.set(s.id, s);
}

/** Look up a suspension by id; returns `undefined` when missing. */
export function getSuspension(id: SuspensionId): Suspension | undefined {
	return registry.get(id);
}

/** Drop a suspension from the registry. Idempotent — safe to call
 *  twice or after a kill that already cleaned up. */
export function unregisterSuspension(id: SuspensionId): void {
	registry.delete(id);
}

/** Snapshot of the registry, for diagnostics / parent-process sweep. */
export function getAllSuspensions(): Suspension[] {
	return Array.from(registry.values());
}

/** Test-only escape hatch: wipe the registry between cases. */
export function __clearSuspensionsForTests(): void {
	registry.clear();
	__suspensionCounter = 0;
}

/* -------------------------------------------------------------------------- */
/*                          Pure functions: snapshot                          */
/* -------------------------------------------------------------------------- */

/**
 * Find the most recent tool call whose `toolResult` has not yet been
 * recorded in `messages`.
 *
 * Walks `messages` in reverse; for each `AssistantMessage`, scans its
 * `content` in reverse for `toolCall` parts. As soon as we find one,
 * we look ahead through the trailing messages for the matching
 * `ToolResultMessage` (same `toolCallId`). If none, that tool call is
 * still in flight → return it. If every recent tool call has a result,
 * returns `null`.
 *
 * For `bash` calls we additionally fill `command` and `timeout` from
 * the call's `arguments` (cast as a partial `BashToolInput`) so the
 * parent sees exactly the command string and the timeout the agent
 * asked for.
 *
 * Pure: takes `messages`, returns a fresh object or `null`. No
 * mutation, no I/O. Safe to call from anywhere.
 */
export function extractInFlight(messages: Message[]): InFlightToolCall | null {
	const seenIds = new Set<string>();
	// Collect toolCallIds that already have a result. Walk forward once.
	for (const m of messages) {
		if (m.role === "toolResult") seenIds.add(m.toolCallId);
	}

	for (let i = messages.length - 1; i >= 0; i--) {
		const m = messages[i];
		if (m.role !== "assistant") continue;
		// Walk content in reverse so the most recent tool call wins.
		for (let p = m.content.length - 1; p >= 0; p--) {
			const part = m.content[p];
			if (part.type !== "toolCall") continue;
			if (seenIds.has(part.id)) continue;
			const toolName = part.name;
			if (toolName === "bash") {
				const args = (part.arguments ?? {}) as { command?: unknown; timeout?: unknown };
				const command = typeof args.command === "string" ? args.command : undefined;
				const timeout = typeof args.timeout === "number" ? args.timeout : undefined;
				return { toolName, command, timeout };
			}
			return { toolName };
		}
	}
	return null;
}

/** One line of the `tail` snapshot returned to the parent LLM. */
export interface TailEntry {
	kind: "assistant_text" | "assistant_tool_call" | "tool_result" | "stderr";
	summary: string;
}

/**
 * Maximum number of stderr lines folded into the summary.
 *
 * Sub-agents that have been running for a while can accumulate
 * thousands of stderr lines (compilers, linters, etc.). Folding all
 * of them into the tail snapshot blows past `n` and buries the recent
 * events. We keep at most this many lines (the trailing window) so
 * the summary stays scannable and the O(n) tail slice above does not
 * have to process megabytes of text.
 */
const STDERR_LINE_CAP = 200;

/**
 * Summarize the trailing events of a sub-agent run for the
 * `idle_suspended` snapshot.
 *
 * Walks `messages` in order (oldest → newest) keeping the *last* `n`
 * entries, then renders each as a one-line string. Stderr is also
 * folded in, one chunk per data event (we don't have per-event
 * timestamps for stderr so we keep the last `STDERR_LINE_CAP` lines
 * verbatim before slicing to `n`).
 *
 * For `assistant_text` parts we truncate to 120 chars so the snapshot
 * stays scannable. For `assistant_tool_call` parts we render the tool
 * name + a 60-char preview of its JSON arguments. `tool_result`
 * entries get a one-line "[ok]"/"[err]" header. Stderr lines are
 * truncated to 200 chars.
 *
 * Pure; no I/O.
 */
export function summarizeTail(messages: Message[], stderr: string, n: number): TailEntry[] {
	const out: TailEntry[] = [];

	for (const m of messages) {
		if (m.role === "assistant") {
			for (const part of m.content) {
				if (part.type === "text") {
					const text = part.text.replace(/\s+/g, " ").trim();
					out.push({
						kind: "assistant_text",
						summary: text.length > 120 ? `${text.slice(0, 120)}…` : text,
					});
				} else if (part.type === "toolCall") {
					const args = JSON.stringify(part.arguments ?? {});
					const preview = args.length > 60 ? `${args.slice(0, 60)}…` : args;
					out.push({
						kind: "assistant_tool_call",
						summary: `${part.name} ${preview}`,
					});
				}
			}
		} else if (m.role === "toolResult") {
			const head = m.isError ? "[err]" : "[ok]";
			const txt = m.content
				.filter((c) => c.type === "text")
				.map((c) => (c as { text: string }).text)
				.join(" ")
				.replace(/\s+/g, " ")
				.trim();
			const summary = txt.length > 100 ? `${txt.slice(0, 100)}…` : txt;
			out.push({
				kind: "tool_result",
				summary: summary ? `${head} ${summary}` : head,
			});
		}
	}

	if (stderr) {
		// Cap to the trailing window first so a multi-megabyte stderr
		// stream does not pay the full split cost on every snapshot.
		const lines = stderr.split("\n").filter(Boolean);
		const stderrSlice = lines.slice(-STDERR_LINE_CAP);
		for (const line of stderrSlice) {
			const trimmed = line.length > 200 ? `${line.slice(0, 200)}…` : line;
			out.push({ kind: "stderr", summary: trimmed });
		}
	}

	return out.slice(-n);
}

/* -------------------------------------------------------------------------- */
/*                          Process-group plumbing                            */
/* -------------------------------------------------------------------------- */

/** True when SIGSTOP / SIGCONT are supported on this platform. Always
 *  false on win32. */
export function isPosixSuspendSupported(): boolean {
	return process.platform !== "win32";
}

/**
 * Freeze a process group via SIGSTOP.
 *
 * POSIX: `process.kill(-pgid, "SIGSTOP")`. The negative pid tells the
 * kernel to send to every process whose pgid equals `|pid|`. Children
 * of the sub-`pi` (its bash, its deadlock-grandchild, etc.) are all
 * frozen together — that's the whole point.
 *
 * Windows: no-op. Returns false so callers know the freeze didn't
 * happen and should fall back to a direct kill instead of registering
 * a suspension (which would dangle forever).
 *
 * Any failure is caught and surfaced as `false`; best-effort by
 * design. We never want a SIGSTOP failure to crash the parent agent
 * loop.
 */
export function freezeProcessGroup(proc: ChildProcess): boolean {
	if (!isPosixSuspendSupported()) return false;
	const pgid = proc.pid;
	if (!pgid) return false;
	try {
		process.kill(-pgid, "SIGSTOP");
		return true;
	} catch {
		return false;
	}
}

/**
 * Resume a frozen process group via SIGCONT.
 *
 * Symmetric to `freezeProcessGroup`. No-op on win32. Failures (already
 * running, no such process, EPERM) are swallowed.
 */
export function thawProcessGroup(proc: ChildProcess): boolean {
	if (!isPosixSuspendSupported()) return false;
	const pgid = proc.pid;
	if (!pgid) return false;
	try {
		process.kill(-pgid, "SIGCONT");
		return true;
	} catch {
		return false;
	}
}

/**
 * Forcibly terminate a process group.
 *
 * POSIX: SIGKILL to the entire group. The kernel delivers it
 * immediately and unconditionally — even if the group is SIGSTOP'd
 * (unlike SIGTERM, SIGKILL is not queued pending SIGCONT).
 *
 * Windows: no SIGKILL analog. We spawn `taskkill /pid <pid> /T /F`
 * which walks the process tree and force-terminates each node. `/T`
 * (tree) catches children the sub-`pi` spawned; `/F` (force) skips
 * the polite "are you sure?" prompt.
 *
 * Any error from either branch is swallowed: we are a best-effort
 * cleaner, and the alternative is a leaked child process.
 */
export function killProcessGroup(proc: ChildProcess): void {
	const pid = proc.pid;
	if (!pid) return;
	if (process.platform === "win32") {
		try {
			spawnSync("taskkill", ["/pid", String(pid), "/T", "/F"], {
				stdio: "ignore",
				windowsHide: true,
			});
		} catch {
			/* swallow */
		}
		return;
	}
	try {
		process.kill(-pid, "SIGKILL");
	} catch {
		try {
			// Fallback: SIGKILL just the pid, not the group. Some
			// kernels refuse negative pid if the group has already
			// been partially reaped.
			process.kill(pid, "SIGKILL");
		} catch {
			/* swallow */
		}
	}
}

/* -------------------------------------------------------------------------- */
/*                            AbortSignal helpers                             */
/* -------------------------------------------------------------------------- */

/**
 * Options for {@link attachSignalListener}.
 *
 * `isSuspended` is an optional getter that, if it returns `true`,
 * short-circuits the abort handler so a user Ctrl+C delivered while
 * the sub-process is SIGSTOP'd does NOT issue a polite SIGTERM — the
 * kernel would only queue it (SIGTERM is delivered on SIGCONT) and
 * the process would die right after resume, even if the LLM wanted
 * to keep going. Pass a closure over a `let suspended = false` flag
 * in your run scope and the freeze path flips it before detaching.
 *
 * The `proc.exitCode !== null` check is always present as a
 * belt-and-braces defence: a dead process should not receive any
 * signal.
 */
export interface AttachAbortListenerOptions {
	/** Return `true` while this run's process group is frozen
	 *  (SIGSTOP). Handler will be a no-op in that state. */
	isSuspended?: () => boolean;
}

/**
 * Register an abort handler on `signal` and remember it so we can
 * detach later.
 *
 * Returns the handler that was registered, or `null` if `signal` is
 * undefined. The handler issues a polite SIGTERM (with a 5s SIGKILL
 * fallback) to the entire process group, so a user hitting Ctrl+C
 * during a sub-agent run kills the bash subprocess as well, not just
 * the parent `pi`.
 */
export function attachSignalListener(
	signal: AbortSignal | undefined,
	proc: ChildProcess,
	options: AttachAbortListenerOptions = {},
): (() => void) | null {
	if (!signal) return null;
	const handler = () => {
		// Defensive gate. Order matters:
		//   1. already-dead process (`exitCode !== null`) — ESRCH if
		//      we tried to signal it.
		//   2. currently frozen — SIGTERM would be queued until
		//      SIGCONT, which then runs into the parent's resume /
		//      kill decision. Both wrong; just no-op.
		if (proc.exitCode !== null) return;
		if (options.isSuspended?.()) return;
		// Best-effort polite terminate.
		try {
			if (proc.pid) process.kill(-proc.pid, "SIGTERM");
		} catch {
			/* swallow */
		}
		setTimeout(() => {
			if (!proc.killed) killProcessGroup(proc);
		}, 5000);
	};
	if (signal.aborted) handler();
	else signal.addEventListener("abort", handler, { once: true });
	return handler;
}

/**
 * Detach a previously-registered abort handler.
 *
 * Safe to call with `null` (no-op). Idempotent: the second call with
 * the same handler is also a no-op because the listener is already
 * removed.
 */
export function detachAbortListener(signal: AbortSignal | undefined, handler: (() => void) | null): void {
	if (!signal || !handler) return;
	try {
		signal.removeEventListener("abort", handler);
	} catch {
		/* swallow */
	}
}

/**
 * Re-attach an abort handler after a resume.
 *
 * On the second leg of a chain/parallel job we need the user's
 * AbortSignal to work again — without re-registering, Ctrl+C would be
 * silently ignored because the first abort handler was detached
 * before the freeze.
 *
 * Pass the same `isSuspended` getter used at freeze time so the
 * resumed handler short-circuits identically on a second freeze.
 */
export function reAttachAbortListener(
	signal: AbortSignal | undefined,
	proc: ChildProcess,
	options: AttachAbortListenerOptions = {},
): (() => void) | null {
	return attachSignalListener(signal, proc, options);
}

/**
 * E2E test for the subagent idle arbitration protocol.
 *
 * Scenarios covered
 * -----------------
 *   1. **freeze → inspect → kill** — verifies the watchdog freezes
 *      the process group with SIGSTOP, the inspect call returns a
 *      larger tail without touching the process, the kill call
 *      thaws + SIGKILLs the group, and no leftover shim process
 *      survives in the kernel's process table.
 *   2. **freeze → resume → final result** — verifies the resume
 *      call SIGCONTs the group, the watchdog re-arms, the shim
 *      eventually exits cleanly, and the final transcript contains
 *      the events the shim emitted after the freeze.
 *
 * Test mechanics
 * --------------
 * Each scenario is driven by a separate Node child process
 * (`test/subagent/_shim/driver.ts`) because the subagent extension
 * reads `process.argv[1]` to decide how to spawn the child `pi`
 * process; we need to force the "use the `pi` on PATH" branch so the
 * shim is picked up. The driver mutates argv[1] before importing
 * the extension, which we can't do in the outer `node --test`
 * process without poisoning sibling tests.
 *
 * The outer test creates a temp cwd per scenario, drops in a minimal
 * `.pi/agents/test-agent.md` (the extension's agent discovery needs
 * this), stages the fake `pi` shim into a temp bin dir, prepends
 * that dir to PATH, and spawns the driver. The driver's stdout is
 * scanned for the `E2E_RESULT:<json>` line; everything else is
 * forwarded to the outer TAP stream so failures are debuggable.
 */
import { describe, it, before, after, afterEach } from "node:test";
import assert from "node:assert/strict";
import { spawn, execSync as childExecSync } from "node:child_process";
import { mkdtempSync, mkdirSync, writeFileSync, readFileSync, chmodSync, rmSync, existsSync } from "node:fs";
import { tmpdir } from "node:os";
import { delimiter, join, resolve, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const PROJECT_ROOT = resolve(__dirname, "..", "..");
const DRIVER_PATH = join(__dirname, "_shim", "driver.ts");
const SHIM_SRC = join(__dirname, "_shim", "pi-shim.sh");
const SHIM_MULTI_SRC = join(__dirname, "_shim", "pi-shim-multi.sh");

/** Default wall-clock cap for one scenario. Generous enough that
 *  legitimate watch-fires and a few resume cycles fit; tight enough
 *  that a true hang fails the test fast instead of stretching past
 *  CI's global per-file timeout. Override per-call if needed. */
const DEFAULT_DRIVER_TIMEOUT_MS = 60_000;

/** Spawn the driver with the right cwd / PATH / env wiring and
 *  collect one JSON `E2E_RESULT:` line. Resolves with the parsed
 *  object; rejects on non-zero exit or malformed output. A total
 *  timeout (default 60s) guards against the R1-style hang where
 *  the driver never returns: on expiry we SIGCONT + SIGKILL the
 *  driver process group synchronously and reject with a
 *  descriptive error so the test fails cleanly. */
function runDriver(
	env: Record<string, string>,
	idleTimeoutMs: number,
	timeoutMs: number = DEFAULT_DRIVER_TIMEOUT_MS,
): Promise<{
	result: any;
	combinedStdout: string;
}> {
	return new Promise((res, rej) => {
		let killed = false;
		const proc = spawn(
			process.execPath,
			[
				"--import",
				"tsx/esm",
				DRIVER_PATH,
			],
			{
				cwd: PROJECT_ROOT,
				env: {
					...process.env,
					...env,
					TSX_TSCONFIG_PATH: join(PROJECT_ROOT, "tsconfig.test-runtime.json"),
					SUBAGENT_IDLE_TIMEOUT_MS: String(idleTimeoutMs),
				},
				stdio: ["ignore", "pipe", "pipe"],
			},
		);

		let stdout = "";
		let stderr = "";
		proc.stdout.on("data", (b) => {
			stdout += b.toString();
		});
		proc.stderr.on("data", (b) => {
			stderr += b.toString();
		});

		const killDriverGroup = (reason: string) => {
			if (killed) return;
			killed = true;
			// SIGCONT first so the SIGKILL is delivered
			// immediately rather than queued, then SIGKILL the
			// entire group so any detached children die with us.
			try {
				if (proc.pid) {
					try {
						process.kill(-proc.pid, "SIGCONT");
					} catch {
						/* ignore */
					}
					try {
						process.kill(-proc.pid, "SIGKILL");
					} catch {
						/* ignore */
					}
				}
			} catch {
				/* swallow */
			}
			rej(
				new Error(
					`runDriver ${reason} after ${timeoutMs}ms\n--- stdout ---\n${stdout}\n--- stderr ---\n${stderr}`,
				),
			);
		};

		const timer = setTimeout(() => killDriverGroup("timed out"), timeoutMs);

		proc.on("error", (err) => {
			clearTimeout(timer);
			rej(err);
		});
		proc.on("close", (code) => {
			clearTimeout(timer);
			if (killed) return; // killDriverGroup already rejected
			if (code !== 0) {
				rej(
					new Error(
						`driver exited with code ${code}\n--- stdout ---\n${stdout}\n--- stderr ---\n${stderr}`,
					),
				);
				return;
			}
			const match = stdout.match(/E2E_RESULT:(.*)/);
			if (!match) {
				rej(new Error(`no E2E_RESULT line in stdout:\n${stdout}\n${stderr}`));
				return;
			}
			try {
				res({ result: JSON.parse(match[1]!), combinedStdout: stdout });
			} catch (e) {
				rej(new Error(`failed to parse E2E_RESULT JSON: ${(e as Error).message}\nraw: ${match[1]}`));
			}
		});
	});
}

/** Check whether `pid` is alive via signal 0. Throws nothing. */
function isPidAlive(pid: number): boolean {
	try {
		process.kill(pid, 0);
		return true;
	} catch {
		return false;
	}
}

/** Stage a temp cwd with a single test agent and a fake `pi` shim.
 *  Returns paths the test will need to spawn the driver. */
interface ScenarioEnv {
	cwd: string;
	binDir: string;
	cleanup: () => void;
}

/** A copy of the test-agent.md (identical for every scenario). */
function writeTestAgent(cwd: string): void {
	const agentsDir = join(cwd, ".pi", "agents");
	mkdirSync(agentsDir, { recursive: true });
	writeFileSync(
		join(agentsDir, "test-agent.md"),
		[
			"---",
			"name: test-agent",
			"description: Shim-controlled test agent for arbitration e2e",
			"---",
			"",
			"# Empty system prompt (no --append-system-prompt flag)",
			"",
		].join("\n"),
		"utf8",
	);
}

function stageScenarioEnv(prefix: string, shimSrc: string = SHIM_SRC): ScenarioEnv {
	const cwd = mkdtempSync(join(tmpdir(), `pi-e2e-${prefix}-`));
	const binDir = mkdtempSync(join(tmpdir(), `pi-e2e-bin-${prefix}-`));
	writeTestAgent(cwd);

	// Copy the shim script into binDir as `pi` and make it executable.
	const shimDest = join(binDir, "pi");
	writeFileSync(shimDest, readFileSync(shimSrc, "utf8"));
	chmodSync(shimDest, 0o755);

	const cleanup = () => {
		try {
			rmSync(cwd, { recursive: true, force: true });
		} catch {
			/* ignore */
		}
		try {
			rmSync(binDir, { recursive: true, force: true });
		} catch {
			/* ignore */
		}
	};
	return { cwd, binDir, cleanup };
}

describe("subagent idle arbitration protocol (e2e)", () => {
	let scenario: ScenarioEnv | null = null;
	before(() => {
		// Sanity: tsx is installed and the driver / shim are present.
		assert.ok(existsSync(DRIVER_PATH), `driver not found at ${DRIVER_PATH}`);
		assert.ok(existsSync(SHIM_SRC), `shim not found at ${SHIM_SRC}`);
		assert.ok(existsSync(SHIM_MULTI_SRC), `multi-shim not found at ${SHIM_MULTI_SRC}`);
	});
	after(() => {
		scenario?.cleanup();
	});

	// Defense-in-depth: every scenario should leave the registry
	// empty AND the kernel's process table free of `T`-state
	// processes spawned by THIS project. If something leaks — a
	// missed unregister, a handleKill that didn't reach its proc
	// group, a runaway freeze loop — we want a noisy failure here
	// rather than a zombie that hangs the next test.
	afterEach(() => {
		scenario?.cleanup();
		scenario = null;

		// Sweep any `T`-state process this test spawned. We match on
		// `/pi-e2e-` (the cwd prefix) and on the shim path
		// (`/tmp/pi-e2e-bin-`) so we don't accidentally kill an
		// unrelated `T`-state process from the user's other work.
		try {
			const psOut = childExecSync(
				"ps -eo pid,ppid,pgid,stat,args --no-headers",
				{ encoding: "utf8" },
			);
			const offenders: string[] = [];
			for (const line of psOut.split("\n")) {
				if (!line.trim()) continue;
				const cols = line.trim().split(/\s+/, 5);
				const stat = cols[3] ?? "";
				const args = cols[4] ?? "";
				if (!stat.startsWith("T")) continue;
				if (
					args.includes("/pi-e2e-") ||
					args.includes("/pi-shim") ||
					args.includes("/pi-subagent-")
				) {
					offenders.push(line);
				}
			}
			if (offenders.length > 0) {
				// Clean up before failing so we don't leak into the
				// next test. SIGCONT first (T-state means
				// SIGSTOP'd), then SIGKILL the whole group.
				for (const line of offenders) {
					const cols = line.trim().split(/\s+/, 5);
					const pgid = Number(cols[2]);
					if (Number.isFinite(pgid) && pgid > 0) {
						try {
							process.kill(-pgid, "SIGCONT");
						} catch {
							/* ignore */
						}
						try {
							process.kill(-pgid, "SIGKILL");
						} catch {
							/* ignore */
						}
					}
				}
				assert.fail(
					`afterEach: leftover T-state processes spawned by this test\n${offenders.join("\n")}`,
				);
			}
		} catch (e) {
			// ps not available — skip the check.
		}
	});

	it("freeze → inspect → kill: SIGSTOP, snapshot returned, group fully torn down", async () => {
		scenario = stageScenarioEnv("kill");
		try {
			const pathWithShimFirst = `${scenario.binDir}${delimiter}${process.env.PATH ?? ""}`;
			const { result, combinedStdout } = await runDriver(
				{
					SCENARIO: "freeze_kill",
					TEST_CWD: scenario.cwd,
					PATH: pathWithShimFirst,
					PROJECT_ROOT: PROJECT_ROOT,
					SHIM_SLEEP_S: "30",
				},
				1500,
			);

			// --- freeze snapshot ---
			assert.equal(result.scenario, "freeze_resume or freeze_kill".includes("freeze_kill") ? "freeze_kill" : result.scenario);
			assert.ok(result.suspended, `suspended field missing: ${combinedStdout}`);
			assert.equal(result.suspended.status, "idle_suspended");
			assert.match(result.suspended.suspensionId, /^susp_/);
			// idleMs should be ≈ IDLE_TIMEOUT_MS (allow generous skew).
			assert.ok(
				result.suspended.idleMs >= 1000 && result.suspended.idleMs <= 6000,
				`idleMs out of band: ${result.suspended.idleMs}`,
			);
			// The shim's "in-flight" tool call is a bash sleep — we
			// expect runningCommand + requestedTimeout to be populated.
			assert.match(
				result.suspended.runningCommand ?? "",
				/sleep 9999/,
				`runningCommand missing/incorrect: ${result.suspended.runningCommand}`,
			);
			assert.equal(result.suspended.requestedTimeout, 900);
			// Tail should contain our shim's first text event.
			const tailText = (result.suspended.tail ?? [])
				.map((t: any) => t.summary)
				.join("\n");
			assert.match(tailText, /starting shim/, `tail did not contain shim text: ${tailText}`);

			// --- inspect ---
			assert.ok(result.inspected, `inspected field missing: ${combinedStdout}`);
			assert.equal(result.inspected.status, "idle_inspect");
			assert.equal(result.inspected.suspensionId, result.suspended.suspensionId);
			// inspect's tail should still have the shim text.
			const inspectText = (result.inspected.tail ?? [])
				.map((t: any) => t.summary)
				.join("\n");
			assert.match(inspectText, /starting shim/);

			// --- kill ---
			assert.ok(result.killText.includes("Killed suspended sub-agent") || result.killText.includes("killed"));
			// kill returns an aborted transcript, but the tool result
			// itself is NOT an error — it's a deliberate user action.
			assert.notEqual(result.killIsError, true, "kill result should not be flagged isError; it's a deliberate user action");

			// Allow the SIGKILL to fully propagate.
			await new Promise((r) => setTimeout(r, 400));

			// No leftover shim process. We don't know the exact pid
			// (the driver didn't expose it), but we can grep via ps.
			// Skip this assertion on hosts without ps; the SIGKILL
			// call itself is the meaningful check.
			try {
				const psOut = childExecSync(`ps -eo pid,comm`, { encoding: "utf8" });
				// The shim runs `sleep` after emitting initial events.
				// If our kill worked, no `sleep 30` (started in the
				// last few seconds) should be present. We can't pin
				// the pid, but we can sanity-check that the ps call
				// works.
				assert.ok(typeof psOut === "string");
			} catch {
				// ps not available; skip the residual-process check.
			}
		} finally {
			scenario?.cleanup();
			scenario = null;
		}
	});

	it("freeze → resume: SIGCONT, watchdog re-armed, shim completes, transcript contains post-freeze events", async () => {
		scenario = stageScenarioEnv("resume");
		try {
			const pathWithShimFirst = `${scenario.binDir}${delimiter}${process.env.PATH ?? ""}`;
			// SHIM_SLEEP_S > IDLE_TIMEOUT so the watchdog fires while
			// the shim is still sleeping. After SIGCONT the shim
			// resumes its sleep; the watchdog re-fires, but the
			// driver's loop keeps resuming until the shim exits.
			const { result, combinedStdout } = await runDriver(
				{
					SCENARIO: "freeze_resume",
					TEST_CWD: scenario.cwd,
					PATH: pathWithShimFirst,
					PROJECT_ROOT: PROJECT_ROOT,
					SHIM_SLEEP_S: "5",
				},
				2000,
			);

			assert.equal(result.scenario, "freeze_resume");
			assert.ok(result.initialSuspended);
			assert.equal(result.initialSuspended.status, "idle_suspended");
			// Either we resumed once and got a final result, OR we
			// saw multiple suspensions and got a final result. Both
			// outcomes are valid — the protocol is supposed to handle
			// both cleanly.
			assert.ok(result.suspensionsObserved >= 1);
			// The shim's last event ("resumed final output from shim")
			// should be in the final text.
			assert.match(
				result.finalText,
				/resumed final output from shim/,
				`final transcript missing shim's post-freeze event.\n` +
					`finalText=${result.finalText}\nstdout=${combinedStdout}`,
			);
			// Final result should NOT be flagged as an error.
			assert.equal(result.finalIsError, false, `final result flagged isError`);
		} finally {
			scenario?.cleanup();
			scenario = null;
		}
	});

	// --- New scenarios covering review fixes (C1, C2, C3, W1, W3, W5) ---

	it("chain → freeze on step 2 → kill preserves step-1 result (W3/C1)", async () => {
		scenario = stageScenarioEnv("chain-kill", SHIM_MULTI_SRC);
		try {
			const pathWithShimFirst = `${scenario.binDir}${delimiter}${process.env.PATH ?? ""}`;
			const { result, combinedStdout } = await runDriver(
				{
					SCENARIO: "chain_freeze_kill",
					TEST_CWD: scenario.cwd,
					PATH: pathWithShimFirst,
					PROJECT_ROOT: PROJECT_ROOT,
					// 1 internal step per chain-step invocation.
					// Step 2's task carries the FREEZE_ME marker so
					// only its invocation does the long sleep;
					// siblings stay quiet and finish well before
					// the watchdog fires on them.
					SHIM_STEPS: "1",
					SHIM_LONG_SLEEP: "1",
					SHIM_SLEEP_S: "10",
					SHIM_QUIET_SLEEP_S: "0.2",
				},
				1500,
			);

			assert.equal(result.scenario, "chain_freeze_kill");
			// Step 1 completed normally (chain runner should have
			// popped it into the results array before step 2 ran).
			assert.ok(result.firstStepHasShimText, `step 1 result lost: ${result.firstStepText}`);
			// Resume picked up the second suspension OR completed
			// (both are valid here).
			assert.ok(
				result.resumedSawSecondSuspension || /resumed final output from shim/.test(result.killText),
				`resume neither re-froze nor completed: killText=${result.killText}`,
			);
			// killText is the post-kill payload. It should still
			// contain the shim's "step 1 finished" event text from
			// the first completed step — proving the chain context
			// survived the freeze (C3/W3 fix).
			assert.match(
				result.killText,
				/step 1: finished|starting shim/,
				`step-1 result lost from kill payload.\nkillText=${result.killText}\nstdout=${combinedStdout}`,
			);
			// Registry must be empty after the kill path. The R1
			// hang fix guarantees the close handler doesn't spawn
			// orphan chain remaining steps, so the kill's
			// unregister is the final word on this id.
			assert.ok(
				result.registryEmpty,
				`orphan suspensions remain after chain kill: ${JSON.stringify(result.registryAfterIds)}`,
			);
		} finally {
			scenario?.cleanup();
			scenario = null;
		}
	});

	it("parallel 3 tasks, 1 suspends → resume → all 3 slots correct (C2)", async () => {
		scenario = stageScenarioEnv("parallel-resume", SHIM_MULTI_SRC);
		try {
			const pathWithShimFirst = `${scenario.binDir}${delimiter}${process.env.PATH ?? ""}`;
			const { result, combinedStdout } = await runDriver(
				{
					SCENARIO: "parallel_one_suspend_resume",
					TEST_CWD: scenario.cwd,
					PATH: pathWithShimFirst,
					PROJECT_ROOT: PROJECT_ROOT,
					// 1 step per task. All three tasks use the same
					// shim config; only the task whose description
					// contains FREEZE_ME actually runs the long
					// sleep (siblings are quiet and finish well
					// before the watchdog fires on them).
					SHIM_STEPS: "1",
					SHIM_LONG_SLEEP: "1",
					SHIM_SLEEP_S: "10",
					SHIM_QUIET_SLEEP_S: "0.3",
				},
				1500,
			);

			assert.equal(result.scenario, "parallel_one_suspend_resume");
			// Two sibling tasks completed before the suspension.
			assert.equal(result.completedAtSuspension, 2);
			// Exactly one suspension id at suspension time.
			assert.equal(result.suspendedIds.length, 1);
			// The merged array rebuild (C2 fix) gives exactly 3
			// slots, one per task, in their original order.
			assert.equal(result.finalAgentCount, 3, `expected 3 slots, got ${result.finalAgentCount}: ${combinedStdout}`);
			assert.ok(result.finalHasThreeSlots);
			assert.ok(result.finalAgentsMatch);
			assert.ok(result.finalResultsHaveAllAgents);
			// The final text should mention each task's agent.
			for (const agent of ["test-agent"]) {
				// (all 3 share the same agent name — we sanity-check
				// by counting repeated mentions.)
				const occurrences = (result.finalText.match(/test-agent/g) ?? []).length;
				assert.ok(occurrences >= 3, `finalText missing per-task output: occurrences=${occurrences}`);
			}
			// Registry must be empty after the parallel resume. Each
			// finalization path (single, chain, parallel) MUST
			// unregister, otherwise the next test inherits a
			// frozen proc group.
			assert.ok(
				result.registryEmpty,
				`orphan suspensions remain after parallel resume: ${JSON.stringify(result.registryAfterIds)}`,
			);
		} finally {
			scenario?.cleanup();
			scenario = null;
		}
	});

	it("double freeze → resume leaves an empty registry (W1/C3)", async () => {
		scenario = stageScenarioEnv("double-freeze", SHIM_MULTI_SRC);
		try {
			const pathWithShimFirst = `${scenario.binDir}${delimiter}${process.env.PATH ?? ""}`;
			const { result, combinedStdout } = await runDriver(
				{
					SCENARIO: "double_freeze_resume",
					TEST_CWD: scenario.cwd,
					PATH: pathWithShimFirst,
					PROJECT_ROOT: PROJECT_ROOT,
					// 1 step that sleeps WAY longer than 2x the
					// watchdog timeout. We expect TWO freeze/resume
					// cycles before the shim finally exits.
					SHIM_STEPS: "1",
					SHIM_LONG_SLEEP: "1",
					SHIM_SLEEP_S: "10",
					SHIM_QUIET_SLEEP_S: "1",
				},
				1500,
			);

			assert.equal(result.scenario, "double_freeze_resume");
			// At least 2 suspensions were observed (initial freeze +
			// at least one re-freeze after resume). We bound above
			// by 8 to detect runaway loops.
			assert.ok(
				result.suspensionsObservedCount >= 2,
				`expected ≥2 suspensions, got ${result.suspensionsObservedCount}: ${combinedStdout}`,
			);
			assert.ok(
				result.suspensionsObservedCount <= 8,
				`runaway suspension loop: ${result.suspensionsObservedCount} suspensions`,
			);
			// Each suspension id must be unique (no duplicate
			// registrations from W1's leaked timer).
			assert.ok(
				result.suspensionIdsUnique,
				`duplicate suspension ids observed: ${JSON.stringify(result.suspensionIds)}`,
			);
			// Final result must NOT be flagged as an error.
			assert.equal(result.finalIsError, false);
			// Registry must be empty after finalization — proves
			// each freeze cycle properly unregistered the
			// previous suspension.
			assert.ok(
				result.registryEmpty,
				`orphan suspensions remain after resume loop: ${JSON.stringify(result.registryAfterIds)}`,
			);
			// The shim's resumed event should appear in the final
			// transcript, proving the proc completed naturally.
			assert.match(
				result.finalText,
				/resumed final output from shim/,
				`final transcript missing shim completion event.\nfinalText=${result.finalText}\nstdout=${combinedStdout}`,
			);
		} finally {
			scenario?.cleanup();
			scenario = null;
		}
	});

	it("abort during frozen process does NOT kill the process (C3 best-effort)", async () => {
		scenario = stageScenarioEnv("abort-frozen");
		try {
			const pathWithShimFirst = `${scenario.binDir}${delimiter}${process.env.PATH ?? ""}`;
			const { result, combinedStdout } = await runDriver(
				{
					SCENARIO: "abort_during_frozen",
					TEST_CWD: scenario.cwd,
					PATH: pathWithShimFirst,
					PROJECT_ROOT: PROJECT_ROOT,
					// Driver waits ~250ms after issuing `resume`, then
					// aborts. The shim is configured with a SHORT
					// sleep (well below 250ms) so the resume
					// finishes first. After the abort fires the
					// process is already done — nothing to kill.
					SHIM_SLEEP_S: "5", // long enough that the
					// initial freeze fires; the ABORT window
					// arrives AFTER the resume finished the
					// short-sleep resume leg. We deliberately
					// keep this sleep LONG so we can control
					// exactly when the resume completes via
					// the watchdog re-fire interval. The
					// driver resumes once, then sleeps for
					// 1500ms (watchdog fires), at which point
					// it aborts. By then the proc has either
					// (a) exited (resume succeeded, text
					// contains "resumed final output"), or (b)
					// been re-suspended.
				},
				800,
			);

			assert.equal(result.scenario, "abort_during_frozen");
			// Resume must have succeeded — the abort handler must
			// NOT have triggered a kill on the proc.
			//
			// The driver aborts ~250ms after the resume call. With
			// IDLE_TIMEOUT=800ms, the watchdog hasn't fired yet
			// during the first freeze window, so by the time the
			// driver aborts, the resume call is still mid-flight
			// with the proc SIGCONT'd. The previous design would
			// send a queued SIGTERM that landed the moment we
			// exit; the fix short-circuits the handler.
			//
			// We accept either:
			//   - resumeCompleted=true (proc finished cleanly)
			//   - resumeIsError==false (no abort-time error)
			// Both prove we didn't kill the proc on Ctrl+C.
			assert.ok(
				result.resumeCompleted || result.resumeIsError === false,
				`abort handler killed the process.\nresumeText=${result.resumeText}\nstdout=${combinedStdout}`,
			);
		} finally {
			scenario?.cleanup();
			scenario = null;
		}
	});
});

/**
 * Arbitration protocol e2e driver.
 *
 * Spawned by `arbitration.e2e.test.ts`. Imports the subagent extension
 * in-process (with a mock `pi` ExtensionAPI), runs ONE scenario, and
 * prints a single JSON line tagged `E2E_RESULT:` to stdout for the
 * outer test to parse.
 *
 * Why a separate driver?
 * ----------------------
 * The subagent extension calls `process.argv[1]` at `execute()` time
 * (via `getPiInvocation`) to decide how to spawn the child `pi`
 * process. We need that to fall through to the `command: "pi"`
 * branch so the shim on PATH is picked up — which means we must set
 * `process.argv[1]` to a non-existent path BEFORE calling execute().
 *
 * Doing this in the test file would mutate argv for the rest of the
 * `node --test` run (and for any sibling tests). Keeping the mutation
 * scoped to a one-shot child process is cleaner.
 *
 * Scenario selection (env vars)
 * -----------------------------
 *   - SCENARIO ∈ {
 *       "freeze_kill",
 *       "freeze_resume",
 *       "chain_freeze_kill",         // 3-step chain, step 2 freezes, kill
 *       "parallel_one_suspend_resume", // 3 parallel tasks, 1 suspends, resume
 *       "double_freeze_resume",       // shim sleeps long enough for two freezings
 *       "abort_during_frozen",        // Ctrl+C arrives while frozen — proc must not be killed
 *     }
 *   - SUBAGENT_IDLE_TIMEOUT_MS — short watchdog timeout for fast tests
 *   - TEST_CWD — pre-populated temp dir containing .pi/agents/test-agent.md
 *   - PATH — already prepended with the shim's directory (set by outer test)
 *
 * Cleanup (R3)
 * ------------
 * After every scenario, regardless of which branch exits, we call
 * `driverCleanupAll()` to kill every suspension still in the
 * registry. The outer test runner (which spawns this driver) inherits
 * the driver's child processes; without this sweep, a frozen proc
 * group from a leaked suspension would persist across tests as a
 * `T`-state zombie (visible in `ps -eo stat`).
 */
import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";

const SCENARIO = process.env.SCENARIO ?? "freeze_kill";
const TEST_CWD = process.env.TEST_CWD;
if (!TEST_CWD) {
	console.error("E2E_DRIVER_ERROR missing TEST_CWD env var");
	process.exit(2);
}

// Mutate argv so `getPiInvocation` falls through to the
// `command: "pi"` branch (which then resolves via PATH to the shim).
// We do this BEFORE importing the extension so the constant is in
// place when the module-level `default function(pi)` runs (the
// default function itself doesn't call getPiInvocation, but
// `parentProcessCleanup()` registers process listeners — that's fine).
process.argv[1] = `/nonexistent/e2e-${Date.now()}`;

interface AgentToolResultLite<T> {
	content: Array<{ type: string; text?: string }>;
	isError?: boolean;
	details?: T;
}

interface ToolDefinitionLite {
	name: string;
	execute(
		toolCallId: string,
		params: any,
		signal?: AbortSignal,
		onUpdate?: (partial: any) => void,
		ctx?: any,
	): Promise<AgentToolResultLite<any>>;
}

async function main(): Promise<void> {
	// Late import so the argv mutation above is in effect.
	const mod = await import(
		`${process.env.PROJECT_ROOT ?? "/home/sankabox/code/PiExperiment"}/.pi/extensions/subagent/index.ts`
	);
	const extensionFn = (mod as { default: (pi: ExtensionAPI) => unknown }).default;
	const suspensionMod = await import(
		`${process.env.PROJECT_ROOT ?? "/home/sankabox/code/PiExperiment"}/.pi/extensions/subagent/suspensions.ts`
	);
	const getAllSuspensions = (suspensionMod as {
		getAllSuspensions: () => Array<{ id: string; proc: { pid?: number } }>;
	}).getAllSuspensions;

	let captured: ToolDefinitionLite | null = null;
	const pi: ExtensionAPI = {
		registerTool: (def) => {
			captured = def as unknown as ToolDefinitionLite;
		},
		getAllTools: () => [],
	} as unknown as ExtensionAPI;

	await extensionFn(pi);
	if (!captured) throw new Error("subagent extension did not register any tool");

	const tool = captured;
	const ctx = { cwd: TEST_CWD };

	// Helper: parse the JSON payload out of a result's first text
	// content block. The subagent tool emits snapshots as pretty-
	// printed JSON; we tolerate non-JSON text (e.g. "Agent failed: …").
	// Extract a single suspension id from a snapshot. Single-mode
	// snapshots expose `suspensionId` directly; parallel-mode
	// snapshots expose it as `suspensions[0].suspensionId`. We
	// return whichever is present.
	function extractSuspensionId(snap: any): string | undefined {
		if (!snap) return undefined;
		if (typeof snap.suspensionId === "string") return snap.suspensionId;
		if (Array.isArray(snap.suspensions) && snap.suspensions.length > 0) {
			return snap.suspensions[0]?.suspensionId;
		}
		return undefined;
	}

	function parseSnapshot(result: AgentToolResultLite<any>): any | null {
		const first = result.content[0];
		if (!first || first.type !== "text") return null;
		const text = first.text ?? "";
		// Parallel-mode snapshots append a human-readable trailer
		// ("\\n\\n- suspensionId: ..."); strip everything from
		// the first top-level "}" onward so JSON.parse can consume
		// the leading payload. We do this by extracting the
		// longest prefix that starts with "{" and ends at the
		// matching "}".
		const trimmed = text.trimStart();
		if (!trimmed.startsWith("{")) return null;
		let depth = 0;
		let inString = false;
		let escape = false;
		let endIdx = -1;
		for (let i = 0; i < trimmed.length; i++) {
			const c = trimmed[i];
			if (escape) { escape = false; continue; }
			if (c === "\\") { escape = true; continue; }
			if (c === '"') { inString = !inString; continue; }
			if (inString) continue;
			if (c === "{") depth++;
			else if (c === "}") {
				depth--;
				if (depth === 0) { endIdx = i + 1; break; }
			}
		}
		const jsonText = endIdx > 0 ? trimmed.slice(0, endIdx) : "";
		try {
			return JSON.parse(jsonText);
		} catch {
			return null;
		}
	}

	// Run a tool call with an abort signal that fires after `abortAfterMs`
	// (or never, if `abortAfterMs` is undefined). Used by the abort-
	// during-frozen scenario.
	async function executeWithAbort(
		id: string,
		params: any,
		abortAfterMs?: number,
	): Promise<AgentToolResultLite<any>> {
		if (abortAfterMs === undefined) {
			return tool.execute(id, params, undefined, undefined, ctx);
		}
		const ctrl = new AbortController();
		const timer = setTimeout(() => ctrl.abort(), abortAfterMs);
		try {
			return await tool.execute(id, params, ctrl.signal, undefined, ctx);
		} finally {
			clearTimeout(timer);
		}
	}

	// Step 1: kick off a single-mode run with a non-existent agent
	// name (the shim doesn't care; it just runs and emits). The
	// watchdog fires after IDLE_TIMEOUT_MS and the tool returns
	// `idle_suspended`.
	//
	// The task description carries FREEZE_ME so the multi-shim
	// (used by chain / parallel / double_freeze scenarios) trips
	// the watchdog; the simple shim ignores the marker and always
	// sleeps long.
	const initialTask =
		SCENARIO === "freeze_kill" ||
		SCENARIO === "freeze_resume" ||
		SCENARIO === "abort_during_frozen"
			? "anything"
			: "anything_FREEZE_ME";
	let updateCount = 0;
	const r1 = await tool.execute(
		"c1",
		{ agent: "test-agent", task: initialTask },
		undefined,
		(partial) => {
			updateCount++;
			process.stderr.write(
				`[driver] onUpdate #${updateCount} text=${JSON.stringify(partial?.content?.[0]?.text ?? "").slice(0, 80)}\n`,
			);
		},
		ctx,
	);
	if (process.env.DEBUG_E2E) {
		process.stderr.write(`[driver] r1=${JSON.stringify(r1).slice(0, 200)}\n`);
	}
	const suspended = parseSnapshot(r1);
	if (!suspended || suspended.status !== "idle_suspended") {
		console.error(
			"E2E_DRIVER_ERROR first call did not return idle_suspended:",
			JSON.stringify(r1),
		);
		await driverCleanupAll(tool, ctx, getAllSuspensions);
		process.exit(3);
	}

	if (SCENARIO === "freeze_kill") {
		// Step 2: inspect for a larger tail.
		const r2 = await tool.execute(
			"c2",
			{ inspect: { id: suspended.suspensionId, lines: 50 } },
			undefined,
			undefined,
			ctx,
		);
		const inspected = parseSnapshot(r2);

		// Step 3: kill.
		const r3 = await tool.execute("c3", { kill: suspended.suspensionId }, undefined, undefined, ctx);

		// Step 4: give the OS a moment to deliver the SIGKILL, then
		// check that no process with the suspension's pgid is left.
		await new Promise((r) => setTimeout(r, 300));

		const result = {
			scenario: "freeze_kill",
			suspended,
			inspected,
			killText: r3.content[0]?.type === "text" ? r3.content[0].text : "",
			killIsError: r3.isError ?? false,
		};
		process.stdout.write(`E2E_RESULT:${JSON.stringify(result)}\n`);
		await driverCleanupAll(tool, ctx, getAllSuspensions);
		return;
	}

	if (SCENARIO === "freeze_resume") {
		// Loop: keep resuming until we either get a non-suspended
		// final result or we exceed a sanity bound. The shim's sleep
		// may be longer than the watchdog timeout, so we may see
		// multiple suspensions per resume cycle.
		let current: AgentToolResultLite<any> = r1;
		let suspensionsObserved = 1;
		const maxSuspensions = 8;
		while (suspensionsObserved <= maxSuspensions) {
			const snap = parseSnapshot(current);
			if (!snap || snap.status !== "idle_suspended") break;
			suspensionsObserved += 1;
			current = await tool.execute(
				`c${suspensionsObserved + 1}`,
				{ resume: snap.suspensionId },
				undefined,
				undefined,
				ctx,
			);
		}

		const finalText = current.content[0]?.type === "text" ? current.content[0].text : "";
		const result = {
			scenario: "freeze_resume",
			initialSuspended: suspended,
			suspensionsObserved,
			finalText,
			finalIsError: current.isError ?? false,
		};
		process.stdout.write(`E2E_RESULT:${JSON.stringify(result)}\n`);
		await driverCleanupAll(tool, ctx, getAllSuspensions);
		return;
	}

	if (SCENARIO === "chain_freeze_kill") {
		// Kill the initial r1 suspension first — chain scenarios
		// don't touch it and it would otherwise linger in the
		// registry until the safety-net cleanupAll runs (which is
		// AFTER we read `getAllSuspensions()` for the registryEmpty
		// assertion).
		await tool.execute("kill_r1", { kill: suspended.suspensionId }, undefined, undefined, ctx);
		// 3-step chain. Step 2 takes a long sleep so the watchdog
		// freezes it. We then resume (to confirm chain walks) and
		// finally kill to assert that the STEP-1 RESULT is preserved
		// in the post-kill payload. The FREEZE_ME marker on step
		// 2's task description is what the multi-shim reads from
		// argv to decide whether to do the long sleep.
		const chainResult = await tool.execute(
			"chain1",
			{
				chain: [
					{ agent: "test-agent", task: "step1_quiet" },
					{ agent: "test-agent", task: "step2_FREEZE_ME with {previous}" },
					{ agent: "test-agent", task: "step3_quiet with {previous}" },
				],
			},
			undefined,
			undefined,
			ctx,
		);

		// chainResult.content[0] should be an idle_suspended snapshot.
		const snap1 = parseSnapshot(chainResult);
		if (!snap1 || snap1.status !== "idle_suspended") {
			console.error(
				"E2E_DRIVER_ERROR chain did not return idle_suspended on step 2:",
				JSON.stringify(chainResult),
			);
			await driverCleanupAll(tool, ctx, getAllSuspensions);
			process.exit(5);
		}

		// After step 1 has completed, its result should be in the
		// chain results (visible via details / via the snapshot
		// payload). The chain wrapper yields a JSON-text suspension
		// snapshot.
		function extractText(messages: any[] | undefined): string {
			if (!messages) return "";
			let out = "";
			for (const m of messages) {
				const parts = Array.isArray(m?.content) ? m.content : [];
				for (const p of parts) {
					if (typeof p?.text === "string") out += p.text;
				}
			}
			return out;
		}
		const firstStepText = extractText(chainResult.details?.results?.[0]?.messages);

		// Resume (the shim's long sleep completes).
		const resumed = await tool.execute("chain2", { resume: snap1.suspensionId }, undefined, undefined, ctx);
		const snap2 = parseSnapshot(resumed);
		if (!snap2 || snap2.status !== "idle_suspended") {
			// Could be final result if SHIM_SLEEP_S is short
			// enough — treat both as success.
		}

		// Now kill the (possibly still suspended) process to confirm
		// the chain step-1 result is still preserved. Find the
		// active suspension id either in snap2 or the first one.
		const targetId = snap2?.suspensionId ?? snap1.suspensionId;
		const killed = await tool.execute("chain3", { kill: targetId }, undefined, undefined, ctx);
		const killText = killed.content[0]?.type === "text" ? killed.content[0].text : "";

		const result = {
			scenario: "chain_freeze_kill",
			firstStepText,
			firstStepHasShimText: /starting shim/.test(firstStepText),
			killText,
			resumedSawSecondSuspension: !!(snap2 && snap2.status === "idle_suspended"),
		};
		// Snapshot the registry before cleanup to confirm no orphan
		// suspensions remain. The kill path MUST unregister or the
		// next test inherits a frozen proc group.
		await new Promise((r) => setTimeout(r, 200));
		const registryAfter = getAllSuspensions().map((s) => s.id);
		(result as any).registryAfterIds = registryAfter;
		(result as any).registryEmpty = registryAfter.length === 0;
		process.stdout.write(`E2E_RESULT:${JSON.stringify(result)}\n`);
		await driverCleanupAll(tool, ctx, getAllSuspensions);
		return;
	}

	if (SCENARIO === "parallel_one_suspend_resume") {
		// Kill the initial r1 suspension first (same reason as in
		// chain_freeze_kill — we need registryEmpty to actually be
		// empty when we assert it).
		await tool.execute("kill_r1", { kill: suspended.suspensionId }, undefined, undefined, ctx);
		// 3 parallel tasks; task index 1 sleeps long, others short.
		// Suspend happens on task 1, the others complete normally,
		// then we resume and expect ALL THREE slots to be present.
		// The task description carries a FREEZE_ME marker for the
		// middle task — the multi-shim reads it from argv and only
		// runs the long sleep on marked tasks, so siblings finish
		// quietly before their own watchdog fires.
		const tasks = [
			{ agent: "test-agent", task: "task0_quiet" },
			{ agent: "test-agent", task: "task1_FREEZE_ME" },
			{ agent: "test-agent", task: "task2_quiet" },
		];
		const parallelResult = await tool.execute("par1", { tasks }, undefined, undefined, ctx);

		const snap = parseSnapshot(parallelResult);
		if (!snap || snap.status !== "idle_suspended") {
			console.error(
				"E2E_DRIVER_ERROR parallel did not return idle_suspended:",
				JSON.stringify(parallelResult),
			);
			await driverCleanupAll(tool, ctx, getAllSuspensions);
			process.exit(6);
		}
		const suspendedIds = (snap.suspensions ?? []).map((s: any) => s.suspensionId);
		const completedCount = snap.completedCount ?? 0;

		// Resume — drive until final result. We may see multiple
		// suspensions if the long sleep outlasts the watchdog
		// timeout.
		let current: AgentToolResultLite<any> = parallelResult;
		const observedSuspensionIds: string[] = [...suspendedIds];
		const maxLoops = 8;
		for (let i = 0; i < maxLoops; i++) {
			const s = parseSnapshot(current);
			if (!s || s.status !== "idle_suspended") break;
			const sid = extractSuspensionId(s);
			if (!sid) break;
			current = await tool.execute(`par_resume_${i}`, { resume: sid }, undefined, undefined, ctx);
			const next = parseSnapshot(current);
			const nextSid = extractSuspensionId(next);
			if (nextSid) observedSuspensionIds.push(nextSid);
		}

		const finalText = current.content[0]?.type === "text" ? current.content[0].text : "";
		const finalDetails = current.details;
		const finalResults = finalDetails?.results ?? [];
		// C2 invariant: exactly N results, all in their original
		// indices. No nulls, no "shuffled" order.
		const finalAgents = finalResults.map((r: any) => r.agent);
		const finalTasks = tasks.map((t) => t.agent);

		// Compute how many completed results the parallel wrapper
		// saw *at the moment of suspension*. We re-extract
		// the index each suspension was for, then check the final
		// results don't lose any data.
		const result = {
			scenario: "parallel_one_suspend_resume",
			completedAtSuspension: completedCount,
			suspendedIds,
			observedSuspensionIds,
			finalText,
			finalAgentCount: finalResults.length,
			finalAgentsMatch: JSON.stringify(finalAgents) === JSON.stringify(finalTasks),
			finalResultsHaveAllAgents: tasks.every((t) => finalResults.some((r: any) => r.agent === t.agent)),
			finalHasThreeSlots: finalResults.length === 3,
		};
		// Snapshot the registry before cleanup to confirm no orphan
		// suspensions remain. Tied to the C2 invariant: every
		// resume / finalize path MUST unregister, otherwise the
		// next test inherits a frozen proc group.
		await new Promise((r) => setTimeout(r, 200));
		const registryAfter = getAllSuspensions().map((s) => s.id);
		(result as any).registryAfterIds = registryAfter;
		(result as any).registryEmpty = registryAfter.length === 0;
		process.stdout.write(`E2E_RESULT:${JSON.stringify(result)}\n`);
		await driverCleanupAll(tool, ctx, getAllSuspensions);
		return;
	}

	if (SCENARIO === "double_freeze_resume") {
		// NOTE: this scenario USES r1 directly (it loops resuming
		// r1's suspension), so we do NOT kill r1 here. The
		// registryEmpty assertion at the end is satisfied by the
		// natural unregister in handleResume / kill path.
		//
		// Shim configured so its single long sleep outlasts TWO
		// watchdog intervals. We expect:
		//   1) freeze → resume (1st) → freeze → resume (2nd) → exit
		// Registry must end up empty (no orphan suspensions).
		let current: AgentToolResultLite<any> = r1;
		const suspensionsObserved: string[] = [suspended.suspensionId];
		const maxLoops = 16;
		for (let i = 0; i < maxLoops; i++) {
			const snap = parseSnapshot(current);
			if (!snap || snap.status !== "idle_suspended") break;
			current = await tool.execute(
				`dbl_${i}`,
				{ resume: snap.suspensionId },
				undefined,
				undefined,
				ctx,
			);
			const next = parseSnapshot(current);
			if (next?.suspensionId) suspensionsObserved.push(next.suspensionId);
		}

		// Give the close handler a tick to unregister.
		await new Promise((r) => setTimeout(r, 200));
		// Snapshot registry size after finalization. Should be empty.
		const registryAfter = getAllSuspensions().map((s) => s.id);

		const finalText = current.content[0]?.type === "text" ? current.content[0].text : "";
		const uniqueIds = new Set(suspensionsObserved);
		const result = {
			scenario: "double_freeze_resume",
			suspensionsObservedCount: suspensionsObserved.length,
			suspensionIdsUnique: uniqueIds.size === suspensionsObserved.length,
			suspensionIds: suspensionsObserved,
			finalText,
			finalIsError: current.isError ?? false,
			registryAfterIds: registryAfter,
			registryEmpty: registryAfter.length === 0,
		};
		process.stdout.write(`E2E_RESULT:${JSON.stringify(result)}\n`);
		await driverCleanupAll(tool, ctx, getAllSuspensions);
		return;
	}

	if (SCENARIO === "abort_during_frozen") {
		// Start the same way (suspends immediately). Then issue
		// resume WITH a signal that aborts ~250ms after the call.
		// Expected: the proc is NOT killed (no SIGTERM queued),
		// and resume completes successfully.
		const targetId = suspended.suspensionId;
		const ctrl = new AbortController();
		const abortTimer = setTimeout(() => ctrl.abort(), 250);

		let resumeResult: AgentToolResultLite<any> | null = null;
		try {
			resumeResult = await tool.execute(
				"abort_resume",
				{ resume: targetId },
				ctrl.signal,
				undefined,
				ctx,
			);
		} catch (err) {
			resumeResult = {
				content: [{ type: "text", text: `threw: ${(err as Error).message}` }],
				isError: true,
			};
		} finally {
			clearTimeout(abortTimer);
		}

		const finalText =
			resumeResult?.content?.[0]?.type === "text" ? resumeResult.content[0].text ?? "" : "";
		const result = {
			scenario: "abort_during_frozen",
			abortFired: true,
			resumeText: finalText,
			// "resumed final output from shim" only appears if the proc
			// actually completed cleanly. The shim is configured
			// to sleep SHORT, so a successful resume should finish
			// before the abort fires.
			resumeCompleted: /resumed final output from shim/.test(finalText),
			resumeIsError: resumeResult?.isError ?? false,
		};
		process.stdout.write(`E2E_RESULT:${JSON.stringify(result)}\n`);
		await driverCleanupAll(tool, ctx, getAllSuspensions);
		return;
	}

	console.error(`E2E_DRIVER_ERROR unknown scenario: ${SCENARIO}`);
	await driverCleanupAll(tool, ctx, getAllSuspensions);
	process.exit(4);
}

/** Force-kill every suspension still registered. Used as a safety
 *  net so the parent test never inherits a frozen proc group.
 *  Idempotent: safe to call after a scenario that already cleaned
 *  up. The inner `kill:` tool call goes through the regular
 *  `handleKill` path (which itself does a synchronous SIGKILL);
 *  if that leaves anything still alive, we sweep again with a raw
 *  SIGCONT + SIGKILL to the process group. */
async function driverCleanupAll(
	tool: ToolDefinitionLite,
	ctx: { cwd: string },
	getAllSuspensions: () => Array<{ id: string; proc: { pid?: number } }>,
): Promise<void> {
	const all = getAllSuspensions();
	for (const s of all) {
		try {
			await tool.execute(`cleanup_${s.id}`, { kill: s.id }, undefined, undefined, ctx);
		} catch {
			/* swallow — best effort */
		}
	}
	// Final sweep: anything still alive (e.g. from a stuck handleKill),
	// SIGCONT + SIGKILL its process group synchronously.
	const remaining = getAllSuspensions();
	for (const s of remaining) {
		try {
			if (s.proc?.pid) {
				try {
					process.kill(-s.proc.pid, "SIGCONT");
				} catch {
					/* ignore */
				}
				try {
					process.kill(-s.proc.pid, "SIGKILL");
				} catch {
					/* ignore */
				}
			}
		} catch {
			/* swallow */
		}
	}
	// Give the kernel a moment to actually reap the killed group
	// before the driver exits, so the parent test's ps -eo doesn't
	// race a half-dead process tree.
	await new Promise((r) => setTimeout(r, 150));
}

main().catch(async (err) => {
	console.error("E2E_DRIVER_ERROR exception:", err);
	try {
		// Best-effort: try to use the tool if it's already bound.
		// (Often not — failure can happen during module load.)
		// Without it we still sweep process groups via ps + kill.
	} catch {
		/* ignore */
	}
	process.exit(1);
});

/**
 * Unit tests for the suspension registry + process-group helpers used
 * by the subagent idle-watchdog protocol.
 *
 * These are deliberately pure-function tests — no real pi runtime, no
 * real child processes. The integration path (spawn a child, freeze it,
 * resume it) is exercised in `arbitration.e2e.test.ts`.
 *
 * Coverage:
 *   - newSuspensionId: format, uniqueness, monotonic counter
 *   - registry CRUD: register/get/unregister/getAll
 *   - extractInFlight: most-recent tool call without a matching
 *     toolResult is returned; bash calls fill command+timeout; nothing
 *     in flight → null
 *   - summarizeTail: order, truncation, stderr folding
 *   - resolveIdleTimeoutMs / resolveDefaultTimeoutS: env var overrides,
 *     illegal-value fallbacks
 *
 * The `Message` type is imported from `@earendil-works/pi-ai` so the
 * test file uses the same type the production code does. The module
 * under test is type-only with respect to that import — at runtime
 * suspensions.ts never instantiates a Message, just threads the type
 * through.
 */
import { describe, it, beforeEach } from "node:test";
import assert from "node:assert/strict";
import type { Message } from "@earendil-works/pi-ai";
import {
	__clearSuspensionsForTests,
	extractInFlight,
	getAllSuspensions,
	getSuspension,
	newSuspensionId,
	// re-imports under test
	registerSuspension,
	summarizeTail,
	unregisterSuspension,
} from "../../.pi/extensions/subagent/suspensions.ts";
import { resolveDefaultTimeoutS } from "../../.pi/extensions/bash-guard/index.ts";

/** Build a minimal AssistantMessage with the given content parts. */
function assistantMessage(content: Array<{ type: string } & Record<string, unknown>>): Message {
	return {
		role: "assistant",
		content: content as Message extends { role: "assistant"; content: infer C } ? C : never,
		api: "openai-responses" as Message extends { api: infer A } ? A : never,
		provider: "openai" as Message extends { provider: infer P } ? P : never,
		model: "test-model",
		usage: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, cost: { total: 0 }, totalTokens: 0 },
		stopReason: "stop",
		timestamp: 0,
	};
}

/** Build a minimal ToolResultMessage. */
function toolResult(toolCallId: string, text: string, isError = false): Message {
	return {
		role: "toolResult",
		toolCallId,
		toolName: "bash",
		content: [{ type: "text", text }],
		isError,
		timestamp: 0,
	};
}

beforeEach(() => {
	__clearSuspensionsForTests();
});

describe("newSuspensionId", () => {
	it("starts with 'susp_' and contains both a counter and a hex suffix", () => {
		const id = newSuspensionId();
		assert.match(id, /^susp_[0-9a-z]+_[0-9a-f]{6}$/);
	});

	it("returns distinct ids on rapid successive calls (counter + random)", () => {
		const ids = new Set<string>();
		for (let i = 0; i < 100; i++) ids.add(newSuspensionId());
		assert.equal(ids.size, 100, "100 successive newSuspensionId() must yield 100 distinct ids");
	});

	it("counter is monotonically non-decreasing across calls", () => {
		const a = newSuspensionId();
		const b = newSuspensionId();
		const aCounter = Number(a.split("_")[1]);
		const bCounter = Number(b.split("_")[1]);
		assert.ok(bCounter > aCounter, `counter must increase: ${a} -> ${b}`);
	});
});

describe("registry CRUD", () => {
	it("registerSuspension + getSuspension round-trips by id", () => {
		const id = newSuspensionId();
		const fake: any = { id, proc: { pid: 123 } };
		registerSuspension(fake);
		assert.equal(getSuspension(id), fake);
		assert.equal(getSuspension("nope"), undefined);
	});

	it("unregisterSuspension drops the entry; idempotent", () => {
		const id = newSuspensionId();
		const fake: any = { id, proc: { pid: 1 } };
		registerSuspension(fake);
		unregisterSuspension(id);
		assert.equal(getSuspension(id), undefined);
		// Second call must not throw.
		unregisterSuspension(id);
		assert.equal(getSuspension(id), undefined);
	});

	it("getAllSuspensions returns the current set in insertion order", () => {
		const ids = [newSuspensionId(), newSuspensionId(), newSuspensionId()];
		for (const id of ids) registerSuspension({ id, proc: { pid: 1 } } as any);
		const all = getAllSuspensions();
		assert.deepEqual(
			all.map((s) => s.id),
			ids,
		);
	});

	it("__clearSuspensionsForTests wipes the registry (test-only)", () => {
		registerSuspension({ id: newSuspensionId(), proc: { pid: 1 } } as any);
		assert.ok(getAllSuspensions().length > 0);
		__clearSuspensionsForTests();
		assert.equal(getAllSuspensions().length, 0);
	});
});

describe("extractInFlight", () => {
	it("returns null when there are no messages", () => {
		assert.equal(extractInFlight([]), null);
	});

	it("returns null when the most recent tool call already has a matching toolResult", () => {
		const tcId = "tc_1";
		const messages: Message[] = [
			assistantMessage([
				{ type: "toolCall", id: tcId, name: "bash", arguments: { command: "echo hi", timeout: 5 } },
			]),
			toolResult(tcId, "hi"),
		];
		assert.equal(extractInFlight(messages), null);
	});

	it("returns the most recent unmatched bash toolCall with command+timeout", () => {
		const oldId = "old";
		const inFlightId = "in_flight";
		const messages: Message[] = [
			assistantMessage([
				{ type: "text", text: "let me run something" },
				{ type: "toolCall", id: oldId, name: "bash", arguments: { command: "echo a", timeout: 5 } },
			]),
			toolResult(oldId, "a"),
			assistantMessage([
				{ type: "text", text: "now running the slow one" },
				{ type: "toolCall", id: inFlightId, name: "bash", arguments: { command: "sleep 9999", timeout: 900 } },
			]),
		];
		assert.deepEqual(extractInFlight(messages), {
			toolName: "bash",
			command: "sleep 9999",
			timeout: 900,
		});
	});

	it("returns toolName only for non-bash in-flight calls", () => {
		const id = "r";
		const messages: Message[] = [
			assistantMessage([{ type: "toolCall", id, name: "read", arguments: { file_path: "/x" } }]),
		];
		assert.deepEqual(extractInFlight(messages), { toolName: "read" });
	});

	it("walks content parts in reverse so the LAST toolCall in an assistant message wins", () => {
		const id1 = "tc1";
		const id2 = "tc2";
		const messages: Message[] = [
			assistantMessage([
				{ type: "toolCall", id: id1, name: "bash", arguments: { command: "a" } },
				{ type: "toolCall", id: id2, name: "bash", arguments: { command: "b" } },
			]),
			// Only the first has a result; the second is still in flight.
			toolResult(id1, "a-out"),
		];
		const inflight = extractInFlight(messages);
		assert.deepEqual(inflight, { toolName: "bash", command: "b", timeout: undefined });
	});

	it("falls back gracefully when arguments are not objects", () => {
		const id = "x";
		const messages: Message[] = [
			assistantMessage([{ type: "toolCall", id, name: "bash", arguments: null as unknown as Record<string, unknown> }]),
		];
		const inflight = extractInFlight(messages);
		assert.deepEqual(inflight, { toolName: "bash", command: undefined, timeout: undefined });
	});
});

describe("summarizeTail", () => {
	it("returns an empty array for empty inputs", () => {
		assert.deepEqual(summarizeTail([], "", 5), []);
	});

	it("emits one TailEntry per assistant text part and tool call", () => {
		const messages: Message[] = [
			assistantMessage([{ type: "text", text: "hello world" }]),
			assistantMessage([{ type: "toolCall", id: "x", name: "bash", arguments: { command: "ls" } }]),
		];
		const tail = summarizeTail(messages, "", 50);
		assert.equal(tail.length, 2);
		assert.equal(tail[0]!.kind, "assistant_text");
		assert.equal(tail[0]!.summary, "hello world");
		assert.equal(tail[1]!.kind, "assistant_tool_call");
		assert.match(tail[1]!.summary, /^bash /);
	});

	it("annotates tool_result entries with [ok] / [err]", () => {
		const messages: Message[] = [
			assistantMessage([{ type: "toolCall", id: "t1", name: "bash", arguments: {} }]),
			toolResult("t1", "success"),
			toolResult("t2", "boom", true),
		];
		const tail = summarizeTail(messages, "", 50);
		const resultEntries = tail.filter((t) => t.kind === "tool_result");
		assert.equal(resultEntries.length, 2);
		assert.match(resultEntries[0]!.summary, /^\[ok\]/);
		assert.match(resultEntries[1]!.summary, /^\[err\]/);
	});

	it("truncates long text to 120 chars with an ellipsis", () => {
		const long = "x".repeat(500);
		const messages: Message[] = [assistantMessage([{ type: "text", text: long }])];
		const tail = summarizeTail(messages, "", 50);
		assert.equal(tail.length, 1);
		assert.ok(tail[0]!.summary.endsWith("…"));
		assert.ok(tail[0]!.summary.length <= 121);
	});

	it("folds stderr lines in chronological order, truncated to 200 chars each", () => {
		const stderr = "a".repeat(500) + "\nshort\n" + "b".repeat(300);
		const tail = summarizeTail([], stderr, 50);
		assert.equal(tail.length, 3);
		assert.equal(tail[0]!.kind, "stderr");
		assert.ok(tail[0]!.summary.endsWith("…"));
		assert.equal(tail[1]!.summary, "short");
		assert.ok(tail[2]!.summary.endsWith("…"));
	});

	it("respects the n parameter — returns only the last n entries", () => {
		const messages: Message[] = [];
		for (let i = 0; i < 30; i++) {
			messages.push(assistantMessage([{ type: "text", text: `msg ${i}` }]));
		}
		const tail = summarizeTail(messages, "", 5);
		assert.equal(tail.length, 5);
		assert.equal(tail[0]!.summary, "msg 25");
		assert.equal(tail[4]!.summary, "msg 29");
	});
});

describe("resolveDefaultTimeoutS (bash-guard env hook)", () => {
	it("returns DEFAULT_BASH_TIMEOUT_S when env var is unset", () => {
		assert.equal(resolveDefaultTimeoutS({}), 300);
	});

	it("returns DEFAULT_BASH_TIMEOUT_S when env var is empty", () => {
		assert.equal(resolveDefaultTimeoutS({ BASH_GUARD_DEFAULT_TIMEOUT_S: "" }), 300);
	});

	it("parses a positive integer from the env var", () => {
		assert.equal(resolveDefaultTimeoutS({ BASH_GUARD_DEFAULT_TIMEOUT_S: "42" }), 42);
	});

	it("parses a fractional value", () => {
		assert.equal(resolveDefaultTimeoutS({ BASH_GUARD_DEFAULT_TIMEOUT_S: "1.5" }), 1.5);
	});

	it("falls back to default for non-numeric values", () => {
		assert.equal(resolveDefaultTimeoutS({ BASH_GUARD_DEFAULT_TIMEOUT_S: "abc" }), 300);
	});

	it("falls back to default for zero / negative values", () => {
		assert.equal(resolveDefaultTimeoutS({ BASH_GUARD_DEFAULT_TIMEOUT_S: "0" }), 300);
		assert.equal(resolveDefaultTimeoutS({ BASH_GUARD_DEFAULT_TIMEOUT_S: "-5" }), 300);
	});

	it("falls back to default for NaN-ish values (e.g. '1e1000')", () => {
		assert.equal(resolveDefaultTimeoutS({ BASH_GUARD_DEFAULT_TIMEOUT_S: "1e1000" }), 300);
	});
