edits.newText:
proc.on("close", (code, signal) => {
				if (suspended) return;
				disarmWatchdog();
				if (buffer.trim()) processLine(buffer);
				// Per Node docs, `code === null` when the process was
				// terminated by a signal (e.g. SIGKILL, SIGTERM). Map
				// that to `exitCode = -1` with `stopReason = "aborted"`
				// so `isFailedResult` returns true; otherwise the
				// parent would treat a signal-killed sub-process as a
				// successful exit (`code ?? 0` = 0). The `signal`
				// argument carries the signal name (e.g. "SIGKILL")
				// when code is null; we surface it in errorMessage for
				// diagnostics.
				if (code === null) {
					currentResult.exitCode = -1;
					currentResult.stopReason = currentResult.stopReason ?? "aborted";
					currentResult.errorMessage = currentResult.errorMessage ??
						(signal ? `Process terminated by signal ${signal}` : "Process terminated by signal");
				} else {
					currentResult.exitCode = code;
				}
				resolve({ kind: "exit", result: { ...currentResult } });
			});

			proc.on("error", (err) => {
				if (suspended) return;
				disarmWatchdog();
				currentResult.exitCode = 1;
				// Surface spawn / IPC errors through the same channel
				// as a signal kill so `isFailedResult` can route the
				// failure to the LLM with the same context.
				if (!currentResult.stopReason) currentResult.stopReason = "error";
				if (!currentResult.errorMessage) {
					currentResult.errorMessage = err ? (err as Error).message : "Child process errored";
				}
				resolve({ kind: "exit", result: { ...currentResult } });
			});

