		// in `runSingleAgent` before the freeze) are STILL attached
		// to these streams — Node preserves EventEmitter listeners
		// across SIGSTOP. They DO short-circuit on the cold-path
		// `suspended` flag, but a second freeze + second resume cycle
		// would have THREE pairs of listeners stacked on the same
		// stream, each parsing the same NDJSON line independently.
		// That's the N-W1 accumulation bug. Strip the cold-path
		// listeners first; then attach fresh ones that consult this
		// leg's `resumedSuspended` flag instead of the cold-path's
		// `suspended` (which never goes back to false).
		//
		// `removeAllListeners` is safe here: the streams are owned by
		// us (we spawned the proc), so no external listener should be
		// attached. The cold-path listener is anonymous but is the
		// only one we ever registered on these streams, so removing
		// all of them is the right move.
		proc.stdout?.removeAllListeners("data");
		proc.stderr?.removeAllListeners("data");

		const onStdoutData = (data: Buffer) => {
			if (resumedSuspended) return;
			lastEventAtMs = Date.now();
			armWatchdog();
			buffer += data.toString();
			const lines = buffer.split("\n");
			buffer = lines.pop() || "";
			for (const line of lines) processLine(line);
		};
		const onStderrData = (data: Buffer) => {
			if (resumedSuspended) return;
			lastEventAtMs = Date.now();
			armWatchdog();
			partial.stderr += data.toString();
		};

		proc.stdout?.on("data", onStdoutData);
		proc.stderr?.on("data", onStderrData);

