const finalizeAndContinue = (result: SingleResult, job: Job) => {
			// N-W5: if handleKill already responded (and un-
			// registered), any late close/error event arriving here
			// is a stale SIGKILL aftermath. Drop it on the floor
			// before we touch anything — in particular, BEFORE any
			// arg-evaluation that would walk `result.messages` or
			// `liteToSingle(...)` and could throw on a half-baked
			// result. The previous code resolved with a (no-output)
			// payload, which was harmless but did work (and was
			// duplicate-resolve-arg-evaluated, which is the bug
			// the N-W5 description targets).
			if (susp.cancelled) return;
			// Re-entrancy guard. If we already resolved (e.g. via
			// the watchdog timer that fired a second freeze), the
			// close handler firing for a SIGKILL'd proc must not
			// spawn anything. `resolve()` is a no-op on the second
			// call, but its argument is evaluated eagerly — that
			// was the R1 orphan-chain-step bug.
			if (finalized) return;
			finalized = true;
			disarmWatchdog();
			unregisterSuspension(susp.id);

			// N-W2: detach the abort handler we re-attached at the
			// top of handleResume so it does not leak into the
			// user's AbortSignal for the rest of the parent's life.
			// The signal may outlast this tool call (chain /
			// parallel subsequent steps share the same signal), and
			// a stale handler would race a SIGTERM with the next
			// freeze / kill decision.
			if (activeAbortHandler) {
				detachAbortListener(susp.originalSignal, activeAbortHandler);
				activeAbortHandler = null;
			}

			if (job.kind === "single") {
				const isError = isFailedResult(result);
				const out = getFinalOutput(result.messages) || "(no output)";
				resolve({
					content: isError
						? [{ type: "text", text: `Agent ${result.stopReason || "failed"}: ${out}` }]
						: [{ type: "text", text: out }],
					details: makeDetails("single")([result]),
					isError,
				});
				return;
			}
			if (job.kind === "chain") {
				// Continue the chain from `job.index` using the partial
				// result we just resumed as step `job.index`.
				const allResults: SingleResult[] = [...job.results.map(liteToSingle), result];
				const previousOutput = getFinalOutput(result.messages);
				resolve(
					runChainRemaining(
						job.steps.slice(job.index + 1),
						job.index + 1,
						previousOutput,
						allResults,
						job.steps,
						ctx,
						signal,
						onUpdate,
						agents,
						allToolNames,
						agentScope,
						discovery,
						makeDetails,
						modelOverride,
					),
				);
				return;
			}
			if (job.kind === "parallel") {
				// N-C2: rebuild a fully-ordered result array of
				// length `tasks.length`. The previous design assumed
				// exactly one suspended task and walked
				// `job.completedResults` as "every other slot". When
				// MULTIPLE tasks freeze concurrently, each suspension
				// was patched with `completedResults` excluding only
				// its OWN index — so a resume on one of them walked
				// past the OTHER suspended task's slot and
				// double-counted. Fix: walk the task list by index
				// and pull completed results only from indices that
				// are neither this leg's `job.index` nor any other
				// still-active suspension. For indices still under
				// another suspension, the slot stays as a placeholder
				// (we keep the snapshot the Suspension holds) and the
				// response remains a `idle_suspended` snapshot
				// pointing the LLM at the remaining ids — NOT a
				// final Parallel: N/N success line.
				const allActive = getAllSuspensions().filter(
					(s) => s.job.kind === "parallel" && s.id !== susp.id,
				);
				const stillSuspendedIndices = new Set<number>();
				for (const s of allActive) {
					if (s.job.kind === "parallel") stillSuspendedIndices.add(s.job.index);
				}

				// Build an index → SingleResult map from this leg's
				// completedResults. completedResults excludes ONLY
				// the just-resumed index; siblings that finished
				// before the freeze are present in their original
				// order. We need the index → lite mapping, but the
				// current Job type does not carry that (it just
				// stores a list). To preserve index fidelity we
				// assume completedResults is already in task-index
				// order — the runParallel patch loop builds it by
				// filtering `allResults` by index, which is index-
				// ordered.
				//
				// Rebuild the index map: walk the tasks array, skip
				// indices that are still suspended or the one we
				// just resumed, and consume from completedResults in
				// order.
				const merged: SingleResult[] = new Array(job.tasks.length);
				let sibCursor = 0;
				for (let i = 0; i < job.tasks.length; i++) {
					if (i === job.index) {
						merged[i] = result;
					} else if (stillSuspendedIndices.has(i)) {
						// Leave a placeholder — the other suspension
						// is still alive and will overwrite this
						// slot on its own resume. The renderer
						// tolerates empty slots; the parent LLM
						// will get a still-suspended snapshot and
						// call resume on the remaining id(s).
						merged[i] = {
							agent: job.tasks[i]!.agent,
							agentSource: "unknown",
							task: job.tasks[i]!.task,
							exitCode: -1,
							messages: [],
							stderr: "",
							usage: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, cost: 0, contextTokens: 0, turns: 0 },
						};
					} else {
