									container.addChild(new Markdown(item.text.trim(), 0, 0, mdTheme));
								}
							} else {
								container.addChild(
									new Text(
										theme.fg("muted", "→ ") + formatToolCall(item.name, item.args, theme.fg.bind(theme)),
