	const tail = summarizeTail(susp.messages, susp.stderr, lines);
	const inFlightLive = extractInFlight(susp.messages);
	const idleMs = Date.now() - susp.lastEventAtMs;
	const text = JSON.stringify(
		{
			status: "idle_inspect",
			suspensionId: susp.id,
			idleMs,
