        if (settled.done) return;
        settled.done = true;
        const errMsg = err instanceof Error ? (err.stack ?? err.message) : String(err);
        console.error(`[subagent] ${context} threw: ${errMsg}`);
        try {
            resolve(makeErrorResult(err));
        } catch (resolveErr) {
            console.error(`[subagent] resolve() in ${context} threw: ${(resolveErr as Error).stack ?? resolveErr}`);
