function safeCallback(
    body: () => void,
    settled: { done: boolean },
    resolve: (result: AgentToolResult<SubagentDetails | SuspendedSnapshot>) => void,
    context: string,
    makeErrorResult: (err: unknown) => AgentToolResult<SubagentDetails | SuspendedSnapshot>,
): void {
    if (settled.done) return;
    try {
        body();
    } catch (err) {
        if (settled.done) return;
        settled.done = true;
        const stack = err instanceof Error ? (err.stack ?? err.message) : String(err);
        console.error(`[subagent] ${context} threw: ${stack}`);
        try {
            resolve(makeErrorResult(err));
        } catch (resolveErr) {
            console.error(
                `[subagent] resolve() in ${context} also threw: ${(resolveErr as Error).stack ?? resolveErr}`,
            );
        }
    }
}
