	proc.on("close", (code, signal) => {
		safeSettle<SingleRunOutcome>(
			settled,
			resolve,
			"cold close handler",
			() => settleError("cold close handler"),
			() => {
				if (settled.done) return;
				if (suspended) return;
				disarmWatchdog();
