		const quickSlot = result.slotIndex?.[2];
		assert.ok(quickSlot, `slot 2 missing: ${JSON.stringify(result.slotIndex)}`);
		assert.equal(quickSlot.exitCode, 0, `quick slot should have exitCode=0, got ${quickSlot.exitCode}`);

